function normalizeNeedleSequence(seq){return Array.isArray(seq)?seq.map(n=>Number(n)).filter(n=>Number.isInteger(n)&&n>=1&&n<=MAX_NEEDLE_NUMBER).slice(0,255):[];}
function formatNeedleSequence(seq){const n=normalizeNeedleSequence(seq);return n.length?n.join(' → '):'';}
function parseHp1(bytes,name=''){
  const b=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes||[]);
  if(b.length!==HP1_SIZE)throw new Error(`HP1-Datei hat ${b.length} Byte; erwartet werden ${HP1_SIZE} Byte.`);
  if(!HP1_MAGIC.every((v,i)=>b[i]===v))throw new Error('HP1-Kennung 55 AA 55 AA fehlt.');
  const count=b[HP1_COUNT_OFFSET];if(!count)throw new Error('HP1 enthält keine Nadelfolge.');
  if(HP1_SEQUENCE_OFFSET+(count-1)*HP1_ENTRY_SIZE>=b.length)throw new Error('HP1-Nadelfolge liegt außerhalb der Datei.');
  const sequence=[];
  for(let i=0;i<count;i++){
    const needle=b[HP1_SEQUENCE_OFFSET+i*HP1_ENTRY_SIZE];
    if(needle<1||needle>MAX_NEEDLE_NUMBER)throw new Error(`Ungültige Nadelnummer ${needle} an Position ${i+1}.`);
    sequence.push(needle);
  }
  return {name,sequence,bytes:b.slice()};
}
