function normalizeThreadState(){
  if(!Array.isArray(appState.machineThreads))appState.machineThreads=[];
  appState.machineThreads=appState.machineThreads.slice(0,4).map(row=>Array.from({length:MAX_NEEDLE_NUMBER},(_,i)=>String(Array.isArray(row)?row[i]||'':'')));
  while(appState.machineThreads.length<4)appState.machineThreads.push(Array(MAX_NEEDLE_NUMBER).fill(''));
  if(!appState.motifThreads||typeof appState.motifThreads!=='object'||Array.isArray(appState.motifThreads))appState.motifThreads={};
  if(!Array.isArray(appState.threadCatalog))appState.threadCatalog=[];
  if(!Array.isArray(appState.customThreads))appState.customThreads=[];
}
function threadId(brand,series,code){return `${String(brand||'').trim()}|${String(series||'').trim()}|${String(code||'').trim()}`;}
function formatThreadLabel(t){return t?`${t.brand} · ${t.series} · ${t.code}${t.name?` · ${t.name}`:''}`:'';}
function normalizeHex(v){const s=String(v||'').trim();return /^#[0-9a-f]{6}$/i.test(s)?s.toLowerCase():'';}
function tintToHex(tints){
  const parts=String(tints||'').split(',').map(Number);if(parts.length<3||parts.slice(0,3).some(v=>!Number.isFinite(v)))return'';
  return '#'+parts.slice(0,3).map(v=>Math.max(0,Math.min(255,Math.round(v*255))).toString(16).padStart(2,'0')).join('');
}
function parseThreadPaletteXml(xml,source){
  const doc=new DOMParser().parseFromString(String(xml||''),'application/xml');
  if(doc.querySelector('parsererror'))throw new Error(`${source.brand} ${source.series}: Farbkarte konnte nicht gelesen werden.`);
  return [...doc.querySelectorAll('color[name]')].map(el=>{
    const raw=String(el.getAttribute('name')||'').trim();const m=raw.match(/^([^\s-]+)(?:\s+-\s+(.*))?$/);if(!m)return null;
    const code=String(m[1]||'').trim(),name=String(m[2]||'').trim();if(!code)return null;
    return {id:threadId(source.brand,source.series,code),brand:source.brand,series:source.series,code,name,hex:tintToHex(el.getAttribute('tints'))};
  }).filter(Boolean);
}
function setThreadCatalog(items,status){
  const map=new Map();const allItems=[...(Array.isArray(items)?items:[]),...(Array.isArray(centralThreadColors)?centralThreadColors:[]),...(Array.isArray(appState.customThreads)?appState.customThreads:[])];allItems.forEach(t=>{
    if(!t||!t.brand||!t.series||!t.code)return;const id=threadId(t.brand,t.series,t.code);
    map.set(id,{id,brand:String(t.brand),series:String(t.series),catalog:String(t.catalog||`${t.brand} ${t.series}`.trim()),code:String(t.code),name:String(t.name||''),type:String(t.type||''),hex:normalizeHex(t.hex)});
  });
  threadCatalog=[...map.values()].sort((a,b)=>a.brand.localeCompare(b.brand,'de')||a.series.localeCompare(b.series,'de')||a.code.localeCompare(b.code,'de',{numeric:true}));
  threadCatalogById=new Map(threadCatalog.map(t=>[t.id,t]));
  threadCatalogByLabel=new Map(threadCatalog.map(t=>[formatThreadLabel(t).toLowerCase(),t]));
  threadCatalogStatus=status||threadCatalogStatus;
  const dl=$('#threadCatalogList');if(dl)dl.innerHTML=threadCatalog.map(t=>`<option value="${escapeHtml(formatThreadLabel(t))}"></option>`).join('');
  const statusText=`${threadCatalogStatus} · ${threadCatalog.length} Garnfarben`;const st=$('#threadCatalogStatus');if(st)st.textContent=statusText;const mst=$('#machineThreadCatalogStatus');if(mst)mst.textContent=statusText;
}
function initThreadCatalog(){
  normalizeThreadState();
  // Frühere Online-/Fallback-Kataloge nicht weiterverwenden.
  // Eigene .tch-Kataloge werden separat vom Produktionsserver geladen.
  if(appState.threadCatalog.length){appState.threadCatalog=[];saveStateSoon();}
  setThreadCatalog([], 'Eigene Garnkataloge');
}
async function refreshThreadCatalog(){
  const sources=Array.isArray(window.HCA_THREAD_CATALOG_SOURCES)?window.HCA_THREAD_CATALOG_SOURCES:[];if(!sources.length)return;
  const jobs=sources.map(async source=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),4500);try{const res=await fetch(source.url,{cache:'no-store',signal:controller.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);const parsed=parseThreadPaletteXml(await res.text(),source);if(parsed.length<(source.min||1))throw new Error(`nur ${parsed.length} Farben gelesen`);return {source,parsed};}finally{clearTimeout(timer);}});
  const results=await Promise.allSettled(jobs),collected=[];let complete=0;
  results.forEach((result,i)=>{if(result.status==='fulfilled'){collected.push(...result.value.parsed);complete++;}else log(`Garnkarte ${sources[i].brand} ${sources[i].series} konnte nicht aktualisiert werden: ${result.reason?.message||result.reason}`);});
  if(complete===sources.length&&collected.length){appState.threadCatalog=collected;setThreadCatalog(collected,'Vollständige Farbkarten lokal geladen');saveStateSoon();log(`Garnkarten geladen: ${sources.map(s=>`${s.brand} ${s.series}`).join(', ')} · ${collected.length} Farben.`);}
}


function centralThreadCatalogName(t){return String(t?.catalog||[t?.brand||'',t?.series||''].filter(Boolean).join(' ')).trim()||'Sonstige';}
