async function loadCentralThreadCatalogs(quiet=true){
  if(!sharedServerReady&&!(await ensureSharedServer(quiet)))return false;
  try{
    const res=await productionFetch('/api/hca-shared/settings/thread-catalogs',{timeoutMs:15000});const data=await res.json();if(!res.ok)throw new Error(data.error||data.detail||`HTTP ${res.status}`);
    centralThreadCatalogs=Array.isArray(data.items)?data.items:[];
    centralThreadColors=centralThreadCatalogs.flatMap(c=>(Array.isArray(c.colors)?c.colors:[]).map(x=>({...x,catalog:x.catalog||c.name||''})));
    setThreadCatalog([],centralThreadCatalogs.length?'Eigene TCH-Garnkataloge':'Keine Garnkataloge importiert');
    renderThreadCatalogSettings();renderMachineTransferPlans();
    return true;
  }catch(err){if(!quiet)alert(`Garnkataloge konnten nicht von der Synology geladen werden:\n${err.message||err}`);log(`Zentrale Garnkataloge nicht verfügbar: ${err.message||err}`);return false;}
}
async function importCentralThreadCatalogFile(file){
  if(!file)return false;if(!/\.tch$/i.test(file.name||'')){alert(`${file.name}: Bitte eine .tch-Datei auswählen.`);return false;}
  if(!sharedServerReady&&!(await ensureSharedServer(false)))return false;
  try{
    const res=await productionFetch(`/api/hca-shared/settings/thread-catalogs/import?filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file,timeoutMs:30000});
    const data=await res.json();if(!res.ok)throw new Error(data.error||data.detail||`HTTP ${res.status}`);
    log(`TCH-Garnkatalog ${data.updated?'aktualisiert':'importiert'}: ${data.item?.name||file.name} · ${data.item?.color_count||0} Farben.`);return true;
  }catch(err){alert(`Garnkatalog ${file.name} konnte nicht importiert werden:\n${err.message||err}`);return false;}
}
async function deleteCentralThreadCatalog(catalogId){
  const item=centralThreadCatalogs.find(x=>String(x.catalog_id)===String(catalogId));if(!item)return;
  if(!await hcaConfirm(`Garnkatalog „${item.name}“ zentral entfernen?\n\nDie aktuelle Nadelbelegung wird nicht verändert, kann aber Farben aus diesem Katalog danach nicht mehr auflösen.`))return;
  try{const res=await productionFetch(`/api/hca-shared/settings/thread-catalogs/${encodeURIComponent(catalogId)}`,{method:'DELETE'});const data=await res.json();if(!res.ok)throw new Error(data.error||data.detail||`HTTP ${res.status}`);await loadCentralThreadCatalogs(false);}catch(err){alert(`Garnkatalog konnte nicht entfernt werden:\n${err.message||err}`);}
}

function resolveThreadInput(value){
  const v=String(value||'').trim();if(!v)return null;
  if(threadCatalogById.has(v))return threadCatalogById.get(v);
  const exact=threadCatalogByLabel.get(v.toLowerCase());if(exact)return exact;
  const compact=v.toLowerCase().replace(/[·|]/g,' ').replace(/\s+/g,' ').trim();
  const matches=threadCatalog.filter(t=>{
    const hay=`${t.brand} ${t.series} ${t.code} ${t.name}`.toLowerCase().replace(/\s+/g,' ');
    return hay===compact||hay.includes(compact);
  });
  return matches.length===1?matches[0]:null;
}
async function resolveThreadCodeInteractive(value){
  const code=String(value||'').trim();if(!code)return null;
  let matches=threadCatalog.filter(t=>String(t.code||'').trim().toLowerCase()===code.toLowerCase());
  if(matches.length===1)return matches[0];
  if(matches.length>1){
    const brands=[...new Set(matches.map(t=>t.brand))];
    const brand=await hcaPrompt(`Farbnummer ${code} ist nicht eindeutig.\n\nHersteller eingeben:\n${brands.join(' / ')}`,brands[0]||'');
    if(brand===null)return null;
    matches=matches.filter(t=>t.brand.toLowerCase()===brand.trim().toLowerCase()||t.brand.toLowerCase().includes(brand.trim().toLowerCase()));
    if(matches.length===1)return matches[0];
    if(matches.length>1){
      const series=[...new Set(matches.map(t=>t.series))];
      const serie=await hcaPrompt(`Bei ${brand} gibt es die Farbnummer ${code} in mehreren Serien.\n\nSerie eingeben:\n${series.join(' / ')}`,series[0]||'');
      if(serie===null)return null;
      matches=matches.filter(t=>t.series.toLowerCase()===serie.trim().toLowerCase()||t.series.toLowerCase().includes(serie.trim().toLowerCase()));
      if(matches.length===1)return matches[0];
    }
    alert(`Farbnummer ${code} konnte mit dieser Herstellerangabe nicht eindeutig zugeordnet werden.`);return null;
  }
  if(!await hcaConfirm(`Farbnummer ${code} ist noch nicht in der Garndatenbank.\n\nJetzt als eigenes Garn anlegen?`))return null;
  const brand=await hcaPrompt('Hersteller:', '');if(!brand)return null;
  const series=await hcaPrompt('Serie:', '');if(!series)return null;
  const name=await hcaPrompt('Bezeichnung (optional):','')||'';
  const hexColor=await hcaPrompt('Vorschaufarbe als HEX, z. B. #e75303 (optional):','')||'';
  const t={id:threadId(brand,series,code),brand:brand.trim(),series:series.trim(),code,name:name.trim(),hex:normalizeHex(hexColor)};
  appState.customThreads=appState.customThreads||[];const old=appState.customThreads.find(x=>threadId(x.brand,x.series,x.code)===t.id);if(old)Object.assign(old,t);else appState.customThreads.push(t);
  setThreadCatalog(threadCatalog,threadCatalogStatus);saveStateSoon();log(`Eigenes Garn angelegt: ${formatThreadLabel(t)}`);return threadForId(t.id)||t;
}
