function bit(b,pos){return (b>>pos)&1;}
function decodeStitchDx(b0,b1,b2){let x=0;x+=bit(b2,2)*81;x-=bit(b2,3)*81;x+=bit(b1,2)*27;x-=bit(b1,3)*27;x+=bit(b0,2)*9;x-=bit(b0,3)*9;x+=bit(b1,0)*3;x-=bit(b1,1)*3;x+=bit(b0,0);x-=bit(b0,1);return x;}
function decodeStitchDy(b0,b1,b2){let y=0;y+=bit(b2,5)*81;y-=bit(b2,4)*81;y+=bit(b1,5)*27;y-=bit(b1,4)*27;y+=bit(b0,5)*9;y-=bit(b0,4)*9;y+=bit(b1,7)*3;y-=bit(b1,6)*3;y+=bit(b0,7);y-=bit(b0,6);return -y;}
function decodePatternPreview(info){
  const type=getFileType(info);if(!type||!info?.bytes)return null;const bytes=info.bytes,start=type==='dst'?DST_HEADER_SIZE:0;
  let x=0,y=0,minX=0,maxX=0,minY=0,maxY=0,block=0,stitches=0,colorChanges=0;const blocks=[[]];
  for(let i=start;i+2<bytes.length;i+=3){const b0=bytes[i],b1=bytes[i+1],b2=bytes[i+2],dx=decodeStitchDx(b0,b1,b2),dy=decodeStitchDy(b0,b1,b2);const nx=x+dx,ny=y+dy;
    if((b2&0b11110011)===0b11110011)break;
    if((b2&0b11000011)===0b11000011){x=nx;y=ny;block++;colorChanges++;if(!blocks[block])blocks[block]=[];continue;}
    if((b2&0b01000011)===0b01000011||(b2&0b10000011)===0b10000011){x=nx;y=ny;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);continue;}
    stitches++;if(dx||dy)blocks[block].push([x,y,nx,ny]);
    x=nx;y=ny;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);
  }
  return {blocks,blockCount:Math.max(1,blocks.length),stitches,colorChanges,minX,maxX,minY,maxY,widthMm:(maxX-minX)/10,heightMm:(maxY-minY)/10};
}
function drawPatternCanvas(canvas,info,assignedOverride=null,stats=null){
  if(!canvas)return;const ctx=canvas.getContext('2d'),preview=decodePatternPreview(info);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);if(!preview){if(stats)stats.textContent='Keine Vorschau verfügbar.';return;}
  const pad=24,w=Math.max(1,preview.maxX-preview.minX),h=Math.max(1,preview.maxY-preview.minY),scale=Math.min((canvas.width-pad*2)/w,(canvas.height-pad*2)/h);const ox=(canvas.width-w*scale)/2-preview.minX*scale,oy=(canvas.height-h*scale)/2-preview.minY*scale;
  const assigned=Array.isArray(assignedOverride)?assignedOverride:getMotifThreadIds(info,preview.blockCount);const fallback=getComputedStyle(document.body).color||'#333';ctx.lineWidth=1;ctx.lineCap='round';ctx.lineJoin='round';
  preview.blocks.forEach((segments,idx)=>{const t=threadForId(assigned[idx]);ctx.strokeStyle=t?.hex||fallback;ctx.beginPath();segments.forEach(([x1,y1,x2,y2])=>{ctx.moveTo(ox+x1*scale,oy+y1*scale);ctx.lineTo(ox+x2*scale,oy+y2*scale);});ctx.stroke();});
  if(stats){const hp=normalizeNeedleSequence(info.needleSequence).length;stats.textContent=`${preview.stitches.toLocaleString('de-DE')} Stiche · ${preview.blockCount} Farbblock${preview.blockCount===1?'':'e'} · ca. ${preview.widthMm.toFixed(1)} × ${preview.heightMm.toFixed(1)} mm${hp&&hp!==preview.blockCount?` · HP1: ${hp} Nadelpositionen`:''}`;}
}
