  const preview=decodePatternPreview(selectedFile);motifThreadDraft=getMotifThreadIds(selectedFile,preview?.blockCount||0);$('#motifThreadTitle').textContent=selectedFile.name;renderMotifThreadRows();$('#motifThreadDialog').showModal();
