function saveMachineThreads(){appState.machineThreads[machineThreadDialogIndex]=[...machineThreadDraft];saveStateSoon();renderInventory();renderMachineTransferPlans();log(`${machines[machineThreadDialogIndex].name}: Nadelbelegung gespeichert.`);$('#machineThreadDialog').close();}
