function applyMissingThreads(){
  if(!missingThreadContext)return;const {machineIndex,plan}=missingThreadContext,row=getMachineThreadIds(machineIndex).slice(),key=overrideKey(machineIndex,selectedFile);if(!jobNeedleOverrides[key])jobNeedleOverrides[key]={};
  for(let i=0;i<plan.missing.length;i++){const mode=$(`[data-missing-mode="${i}"]`)?.value,needle=Number($(`[data-missing-needle="${i}"]`)?.value),missing=plan.missing[i];if(!needle)continue;if(mode==='change'){row[needle-1]=missing.threadId;delete jobNeedleOverrides[key][missing.blockIndex];}else{if(!row[needle-1]){alert(`Nadel ${needle} ist laut Maschinenbelegung leer. Für einen Ersatz bitte eine belegte Nadel wählen.`);return;}jobNeedleOverrides[key][missing.blockIndex]=needle;}}
  appState.machineThreads[machineIndex]=row;saveStateSoon();renderInventory();$('#missingThreadDialog').close();missingThreadContext=null;const recheck=resolveThreadPlan(machineIndex,selectedFile);if(recheck.missing?.length){openMissingThreads(machineIndex,recheck);return;}alert('Garn-/Nadelzuordnung ist jetzt vollständig. Die Übertragung kann gestartet werden.');
}
async function prepareThreadPlans(targets){
  const plans=new Map();for(const m of targets){
    // HCA 4 uses the floppy path. HP1 needle selection is not part of the
    // confirmed floppy format yet, so it must not block the TAP transfer.
    if(m.kind==='pico'){log(`${m.name}: Pico/Floppy: Musterdatei wird ohne automatische HP1-Nadelzuordnung übertragen.`);continue;}
    const plan=resolveThreadPlan(m.index,selectedFile);if(!plan.active)continue;if(plan.error){alert(plan.error);if(plan.error.includes('Farbblöcken')||plan.error.includes('Garnfarben'))openMotifPreview();return null;}if(plan.missing?.length){openMissingThreads(m.index,plan);return null;}plans.set(m.index,plan);
  }return plans;
}

