  if(fav)fav.href=FIXED_APP_ICON_URL;if(img){img.src=FIXED_APP_ICON_URL;img.classList.remove('hidden');}empty?.classList.add('hidden');if(remove){remove.disabled=true;remove.classList.add('hidden');}
