function makeEmbroideryLabelMotif(info){
  const preview=decodePatternPreview(info);if(!preview)return '';
  const canvas=document.createElement('canvas');canvas.width=360;canvas.height=250;const ctx=canvas.getContext('2d');
  ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);
  const pad=14,w=Math.max(1,preview.maxX-preview.minX),h=Math.max(1,preview.maxY-preview.minY),scale=Math.min((canvas.width-pad*2)/w,(canvas.height-pad*2)/h);
  const ox=(canvas.width-w*scale)/2-preview.minX*scale,oy=(canvas.height-h*scale)/2-preview.minY*scale;
  ctx.strokeStyle='#000';ctx.lineWidth=1.7;ctx.lineCap='round';ctx.lineJoin='round';
  preview.blocks.forEach(segments=>{ctx.beginPath();segments.forEach(([x1,y1,x2,y2])=>{ctx.moveTo(ox+x1*scale,oy+y1*scale);ctx.lineTo(ox+x2*scale,oy+y2*scale);});ctx.stroke();});
  return canvas.toDataURL('image/png');
}
