  const out={};CARE_PROFILE_KEYS.forEach(k=>{const r=raw&&typeof raw[k]==='object'?raw[k]:{};out[k]={text:String(r.text??def[k].text),svgs:Array.from({length:4},(_,i)=>String(Array.isArray(r.svgs)?r.svgs[i]||'':'')),svgNames:Array.from({length:4},(_,i)=>String(Array.isArray(r.svgNames)?r.svgNames[i]||'':'')),useStandard:k==='standard'?false:(r.useStandard!==undefined?!!r.useStandard:def[k].useStandard)};});appState.settings.labelCareProfiles=out;return out;
