function careTechniqueKey(info={}){const s=String(info.technique||info.techniques||info.method||info.print_type||'').toLowerCase();if(s.includes('stick'))return'stick';if(s.includes('dtf'))return'dtf';if(s.includes('flex'))return'flex';if(s.includes('flock'))return'flock';return'standard';}
