function careTextLines(profile){return String(profile?.text||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean).slice(0,2);}
function validateCareProfileTexts(){const p=normalizeLabelCareProfiles();for(const k of CARE_PROFILE_KEYS){if(k!=='standard'&&p[k].useStandard!==false)continue;const lines=String(p[k].text||'').split(/\r?\n/);if(lines.filter(Boolean).length>2)throw new Error(`${CARE_PROFILE_LABELS[k]}: maximal 2 Textzeilen.`);if(lines.some(x=>x.length>55))throw new Error(`${CARE_PROFILE_LABELS[k]}: maximal 55 Zeichen je Textzeile.`);}}
