function captureCareSettingsEditor(){const k=activeCareEditorKey(),p=normalizeLabelCareProfiles()[k];if($('#settingCareText'))p.text=$('#settingCareText').value;if(k!=='standard'&&$('#settingCareUseStandard'))p.useStandard=$('#settingCareUseStandard').checked;}
