    const raw=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result||''));fr.onerror=()=>reject(fr.error||new Error('Datei konnte nicht gelesen werden'));fr.readAsDataURL(file);});
