async function loadWarehouseStructure(){
  const host=$('#warehouseTree');if(!host)return;
  if(!productionServerConfigured()){host.innerHTML='<div class="inventory-empty-state">Produktionsserver ist nicht eingestellt.</div>';return;}
  host.innerHTML='<div class="inventory-detail-loading">Lagerstruktur wird geladen …</div>';
  try{
    const res=await productionFetch('/api/hca-shared/inventory/warehouses',{timeoutMs:30000});const data=await res.json();
    if(!res.ok)throw new Error(data.detail||data.error||`HTTP ${res.status}`);
    warehouseCache=Array.isArray(data.warehouses)?data.warehouses:[];renderWarehouseStructure();
  }catch(err){host.innerHTML=`<div class="inventory-empty-state">Lagerstruktur konnte nicht geladen werden: ${escapeHtml(err.message||String(err))}</div>`;}
}
function warehouseCounts(){
  let racks=0,bins=0,qty=0;for(const w of warehouseCache){racks+=(w.racks||[]).length;for(const r of w.racks||[]){bins+=(r.bins||[]).length;for(const b of r.bins||[])qty+=Number(b.quantity)||0;}}
  return {warehouses:warehouseCache.length,racks,bins,qty};
}
