async function editWarehouse(id){const w=findWarehouse(id);if(!w)return;const name=await hcaPrompt('Lagername:',w.name||'');if(name===null||!name.trim())return;const code=await hcaPrompt('Lagercode:',w.code||'')??w.code;try{await warehouseJson(`/api/hca-shared/inventory/warehouses/${encodeURIComponent(id)}`,'PUT',{name:name.trim(),code:String(code).trim()});await loadWarehouseStructure();}catch(e){alert(`Lager konnte nicht geändert werden:\n${e.message||e}`)}}
async function deleteWarehouse(id){const w=findWarehouse(id);if(!w||!await hcaConfirm(`Lager „${w.name}“ wirklich löschen?\n\nNur leere Lager ohne Regale können gelöscht werden.`))return;try{await warehouseJson(`/api/hca-shared/inventory/warehouses/${encodeURIComponent(id)}`,'DELETE');await loadWarehouseStructure();}catch(e){alert(e.message||e)}}
