async function editRack(id){const x=findRack(id);if(!x)return;const name=await hcaPrompt('Regalname:',x.name||'');if(name===null||!name.trim())return;const code=await hcaPrompt('Regalcode:',x.code||'')??x.code;try{await warehouseJson(`/api/hca-shared/inventory/racks/${encodeURIComponent(id)}`,'PUT',{name:name.trim(),code:String(code).trim(),sort_order:Number(x.sort_order)||0});await loadWarehouseStructure();}catch(e){alert(e.message||e)}}
