async function editBin(id){const x=findBin(id);if(!x)return;const name=await hcaPrompt('Fachnummer / Name:',x.name||'');if(name===null||!name.trim())return;const code=await hcaPrompt('Fachcode:',x.code||'')??x.code;try{await warehouseJson(`/api/hca-shared/inventory/bins/${encodeURIComponent(id)}`,'PUT',{name:name.trim(),code:String(code).trim(),sort_order:Number(x.sort_order)||0});await loadWarehouseStructure();}catch(e){alert(e.message||e)}}
