function binLabelPrintSettings(){const width=Math.max(20,Number(appState.settings?.binLabelWidth)||75),height=Math.max(20,Number(appState.settings?.binLabelHeight)||50),raw=Number(appState.settings?.binLabelRotation)||0,rotation=[0,90,180,270].includes(raw)?raw:0,printer=String(appState.settings?.binLabelPrinter||appState.settings?.inventoryLabelPrinter||appState.settings?.productLabelPrinter||'').trim();return {width,height,rotation,printer};}
function renderBinLabelCanvas(bin={}){const c=document.createElement('canvas');c.width=1500;c.height=1000;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#000';ctx.strokeStyle='#000';ctx.textBaseline='alphabetic';const left=110,right=1390;ctx.font='700 38px Arial';ctx.fillText(String(bin.warehouse_name||'LAGER'),left,105);ctx.font='700 34px Arial';ctx.fillText(String(bin.rack_name||bin.rack_code||'REGAL'),left,165);ctx.textAlign='center';inventoryLabelFitFont(ctx,String(bin.name||bin.code||'FACH'),right-left,150,82,'900');ctx.fillText(String(bin.name||bin.code||'FACH'),750,390);ctx.textAlign='left';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(left,450);ctx.lineTo(right,450);ctx.stroke();drawCode128B(ctx,String(bin.barcode||''),left,520,right-left,245);ctx.font='800 34px ui-monospace,Consolas,monospace';ctx.textAlign='center';ctx.fillText(String(bin.barcode||''),750,825);ctx.textAlign='left';ctx.font='700 27px Arial';ctx.fillText('HCA LAGERPLATZ',left,935);return c;}
async function printWarehouseBinLabel(bin,copies=1){const cfg=binLabelPrintSettings();if(!cfg.printer)throw new Error('Bitte unter Einstellungen → Lagerplatzetikett einen Drucker einstellen.');const base=renderBinLabelCanvas(bin),canvas=rotateInventoryLabelCanvas(base,cfg.rotation),swap=cfg.rotation===90||cfg.rotation===270,printWidth=swap?cfg.height:cfg.width,printHeight=swap?cfg.width:cfg.height,blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw new Error('Lagerplatzetikett konnte nicht erzeugt werden.');const bytes=await blob.arrayBuffer(),qs=new URLSearchParams({printer:cfg.printer,width_mm:String(printWidth),height_mm:String(printHeight)});for(let i=0;i<Math.max(1,Number(copies)||1);i++){const res=await fetch('/api/print/image?'+qs.toString(),{method:'POST',headers:{'Content-Type':'image/png'},body:bytes});const data=await res.json();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);}return true;}
