async function loadInventory(){
  if(!productionServerConfigured()){inventoryStockCache=[];inventoryArticleListCache=[];inventoryProposalCache=[];renderStockInventory();return;}
  try{
    const q=String($('#inventorySearch')?.value||'').trim();
    const [sr,pr,stockRes,articleRes]=await Promise.all([
      productionFetch('/api/hca-shared/inventory/summary',{timeoutMs:30000}),
      productionFetch('/api/hca-shared/inventory/proposals',{timeoutMs:30000}),
      productionFetch(`/api/hca-shared/inventory/stock?q=${encodeURIComponent(q)}&limit=5000`,{timeoutMs:30000}),
      productionFetch(`/api/hca-shared/inventory/articles?q=${encodeURIComponent(q)}&limit=5000`,{timeoutMs:30000})
    ]);
    const summary=await sr.json(),props=await pr.json(),stock=await stockRes.json();
    let articles={};try{articles=await articleRes.json();}catch{}
    if(!sr.ok)throw new Error(summary.detail||summary.error||`HTTP ${sr.status}`);
    if(!pr.ok)throw new Error(props.detail||props.error||`HTTP ${pr.status}`);
    if(!stockRes.ok)throw new Error(stock.detail||stock.error||`HTTP ${stockRes.status}`);
    inventoryStockCache=Array.isArray(stock.items)?stock.items:[];
    // v0.9.41: the visible article list comes from the article master. This keeps
    // synchronized WooCommerce products visible even when no stock variant row exists.
    inventoryArticleListCache=articleRes.ok&&Array.isArray(articles.items)?articles.items:inventoryGroupRows(inventoryStockCache);
    inventoryProposalCache=Array.isArray(props.items)?props.items:[];
    $('#inventoryPhysical').textContent=Number(summary.physical)||0;$('#inventoryReserved').textContent=Number(summary.reserved)||0;$('#inventoryAvailable').textContent=Number(summary.available)||0;$('#inventoryProposalQty').textContent=Number(summary.proposal_qty)||0;const badge=$('#inventoryBadge');if(badge)badge.textContent=Number(summary.proposal_items)||0;renderStockInventory();
  }
  catch(err){const host=$('#inventoryStockList');if(host)host.innerHTML=`<div class="inventory-empty-state">Lagerdaten nicht verfügbar: ${escapeHtml(err.message||String(err))}</div>`;}
}
function inventoryGroupRows(rows=[]){
  const map=new Map();
  for(const row of rows){
    const key=String(row.article_id||row.article_woo_product_id||row.woo_product_id||row.article_sku||row.sku||row.article||row.id||'');
    if(!map.has(key))map.set(key,{key,article_id:String(row.article_id||''),article:row.article||row.sku||'Artikel',article_sku:row.article_sku||'',manufacturer:row.manufacturer||'',supplier:row.supplier||'',image_url:row.image_url||'',woo_product_id:row.article_woo_product_id||row.woo_product_id||'',variants:[]});
    map.get(key).variants.push(row);
  }
  return [...map.values()].map(g=>{
    g.physical_qty=g.variants.reduce((a,x)=>a+(Number(x.physical_qty)||0),0);
    g.reserved_qty=g.variants.reduce((a,x)=>a+(Number(x.reserved_qty)||0),0);
    g.available_qty=g.variants.reduce((a,x)=>a+(Number(x.available_qty)||0),0);
    g.proposal_qty=g.variants.reduce((a,x)=>a+(Number(x.proposal_qty)||0),0);
    g.on_order_qty=g.variants.reduce((a,x)=>a+(Number(x.on_order_qty)||0),0);
    g.colors=[...new Set(g.variants.map(x=>String(x.color||'').trim()).filter(Boolean))];
    g.sizes=[...new Set(g.variants.map(x=>String(x.size||'').trim()).filter(Boolean))];
    return g;
  }).sort((a,b)=>String(a.article||'').localeCompare(String(b.article||''),'de',{numeric:true,sensitivity:'base'}));
}
function inventoryTextValue(value){
  if(value===null||value===undefined||value==='')return '–';
  if(typeof value==='boolean')return value?'Ja':'Nein';
  if(typeof value==='object'){try{return JSON.stringify(value,null,2);}catch{return String(value);}}
  return String(value);
}
function inventoryPlainText(html){
  const div=document.createElement('div');div.innerHTML=String(html||'');return String(div.textContent||div.innerText||'').trim();
}
function inventoryDetailRows(entries=[]){
  return entries.map(([label,value])=>`<div class="inventory-detail-kv"><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(inventoryTextValue(value))}</dd></div>`).join('');
}
