async function fetchInventoryArticleDetails(articleId,force=false){
  articleId=String(articleId||'');if(!articleId)return null;
  if(!force&&inventoryArticleDetailCache.has(articleId))return inventoryArticleDetailCache.get(articleId);
  const res=await productionFetch(`/api/hca-shared/inventory/articles/${encodeURIComponent(articleId)}`,{timeoutMs:30000});const data=await res.json();
  if(!res.ok)throw new Error(data.detail||data.error||`HTTP ${res.status}`);
  const article=data.article||{};inventoryArticleDetailCache.set(articleId,article);return article;
}
async function loadInventoryArticleDetails(articleId,host){
  if(!articleId||!host)return;host.innerHTML='<div class="inventory-detail-loading">Produktdaten werden geladen …</div>';
  try{host.innerHTML=renderInventoryArticleDetails(await fetchInventoryArticleDetails(articleId));}
  catch(err){host.innerHTML=`<div class="inventory-empty-state">Produktdaten konnten nicht geladen werden: ${escapeHtml(err.message||String(err))}</div>`;}
}
function inventoryMetaEntries(article={}){const meta=Array.isArray(article?.woo?.meta_data)?article.woo.meta_data:[];return meta.map(m=>[String(m?.key||''),m?.value]);}
