function inventoryFormatMoney(v){if(v===null||v===undefined||String(v).trim()==='')return '–';const n=Number(String(v).replace(',','.'));return Number.isFinite(n)?`${n.toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})} €`:inventoryTextValue(v);}
