  return `<div class="inventory-dolibarr-grid"><section class="inventory-info-card"><h3>Produktionsbereiche</h3>${areas?areaHtml:'<div class="inventory-detail-empty">Keine Werbeanbringungsbereiche in den WooCommerce-Daten gefunden.</div>'}</section><section class="inventory-info-card"><h3>Produktionsdaten</h3><dl class="inventory-product-data-grid">${inventoryDetailRows([['Gemischte Druckarten erlaubt',mixed],['Farbdefinitionen',Array.isArray(colors)?`${colors.length} Farben`:colors?'vorhanden':'–'],['Druckbereiche',areaArr.length||'–'],['Größen aktiviert',inventoryMetaValue(article,'_wst_sizes_enabled')],['Eigene Größen',inventoryMetaValue(article,'_wst_custom_sizes')],['Größenläufe',inventoryMetaValue(article,'_wst_size_runs')]])}</dl></section></div>`;
