function businessMoney(v){return new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(Number(v)||0)}
function businessDate(v){if(!v)return '–';try{return new Intl.DateTimeFormat('de-DE').format(new Date(String(v).length<=10?`${v}T00:00:00`:v))}catch{return String(v)}}
function businessStatusPill(status,kind='quote'){const map=kind==='order'?BUSINESS_ORDER_STATUS_LABELS:BUSINESS_QUOTE_STATUS_LABELS,label=map[status]||status||'–';return `<span class="business-status status-${escapeHtml(status||'unknown')}">${escapeHtml(label)}</span>`}
function businessApi(path,options={}){return productionFetch(`/api/hca-shared${path}`,options).then(async res=>{let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.detail||data.error||`HTTP ${res.status}`);return data})}

let businessDocumentSettings={};
const DOCUMENT_SETTING_FIELDS={company_name:'settingDocumentCompany',street:'settingDocumentStreet',postal_code:'settingDocumentPostalCode',city:'settingDocumentCity',country:'settingDocumentCountry',phone:'settingDocumentPhone',email:'settingDocumentEmail',website:'settingDocumentWebsite',vat_id:'settingDocumentVatId',account_holder:'settingDocumentAccountHolder',bank_name:'settingDocumentBankName',iban:'settingDocumentIban',bic:'settingDocumentBic'};
async function loadDocumentSettings(showError=false){
  if(!productionServerConfigured())return false;
  const status=$('#documentSettingsStatus');
  try{const data=await businessApi('/business/document-settings');businessDocumentSettings=data.settings||{};Object.entries(DOCUMENT_SETTING_FIELDS).forEach(([key,id])=>{const el=$(`#${id}`);if(el)el.value=businessDocumentSettings[key]||''});if(status)status.textContent='Zentral gespeichert';return true}
  catch(err){if(status)status.textContent='Nicht verfügbar';if(showError)alert(`Briefpapierdaten konnten nicht geladen werden:\n${err.message||err}`);return false}
}
async function saveDocumentSettings(){
  const payload={};Object.entries(DOCUMENT_SETTING_FIELDS).forEach(([key,id])=>payload[key]=$(`#${id}`)?.value.trim()||'');
  const status=$('#documentSettingsStatus');
  try{const data=await businessApi('/business/document-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});businessDocumentSettings=data.settings||payload;if(status)status.textContent='Zentral gespeichert';alert('Die Briefpapierdaten wurden zentral gespeichert.')}
  catch(err){if(status)status.textContent='Fehler';alert(`Briefpapierdaten konnten nicht gespeichert werden:\n${err.message||err}`)}
}
async function printBusinessPdf(path,filename='HCA-Dokument.pdf'){
  try{
    const response=await productionFetch(`/api/hca-shared${path}`,{cache:'no-store',timeoutMs:60000});
    if(!response.ok){let message=`HTTP ${response.status}`;try{const data=await response.json();message=data.detail||data.error||message}catch{}throw new Error(message)}
    const blob=await response.blob(),url=URL.createObjectURL(blob),frame=document.createElement('iframe');
    frame.title=filename;frame.style.cssText='position:fixed;width:1px;height:1px;right:0;bottom:0;border:0;opacity:0;pointer-events:none';frame.src=url;document.body.appendChild(frame);
    frame.onload=()=>setTimeout(()=>{try{frame.contentWindow?.focus();frame.contentWindow?.print()}catch{}},350);
    setTimeout(()=>{URL.revokeObjectURL(url);frame.remove()},120000);return true;
  }catch(err){alert(`PDF konnte nicht erstellt werden:\n${err.message||err}`);return false}
}
