  $('#businessAddContact')?.addEventListener('click',()=>openBusinessContactDialog());$('#businessAddAddress')?.addEventListener('click',()=>openBusinessAddressDialog());
  host.querySelectorAll('[data-edit-business-contact]').forEach(b=>b.onclick=()=>openBusinessContactDialog(contacts.find(x=>x.id===b.dataset.editBusinessContact)||{}));
