function businessQuoteLineAmounts(line){const cfg=line.config||{},qty=Object.keys(cfg.sizes||{}).length?Object.values(cfg.sizes).reduce((a,v)=>a+(Number(v)||0),0):Number(line.quantity)||0,steps=Array.isArray(cfg.production_steps)?cfg.production_steps:[],refUnit=steps.reduce((a,x)=>a+(Number(x?.unit_price)||0),0),setup=steps.reduce((a,x)=>a+(Number(x?.setup_price)||0),0),discount=Math.max(0,Math.min(100,Number(line.discount_pct)||0)),net=qty*((Number(line.unit_price)||0)+refUnit)*(1-discount/100)+setup,tax=net*(Number(line.tax_rate)||0)/100;return {qty,refUnit,setup,net,tax,gross:net+tax}}
