// Finanzen / Rechnungen / Lexware Office v0.10.3
// ---------------------------------------------------------------------------
const FINANCE_STATUS_LABELS={draft:'Entwurf',open:'Offen',paid:'Bezahlt',paidoff:'Bezahlt',voided:'Storniert',cancelled:'Storniert',overdue:'Überfällig'};
function financeToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function financeDatePlus(days=14){const d=new Date();d.setDate(d.getDate()+Number(days||0));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function financeInvoiceStatusPill(inv={}){const paid=String(inv.payment_status||'')==='paid'||['paid','paidoff'].includes(String(inv.status||''));const st=paid?'paid':String(inv.status||'open');const label=FINANCE_STATUS_LABELS[st]||st||'Offen';return `<span class="business-status finance-status status-${escapeHtml(st)}">${escapeHtml(label)}</span>`}
function financeSourceLabel(inv={}){if(inv.source==='woocommerce')return '<span class="finance-source source-woo">WooCommerce</span>';if(inv.source==='lexware_external')return '<span class="finance-source source-lexware">Lexware</span>';return '<span class="finance-source source-hca">HCA</span>'}
function lexwareBadge(inv={}){if(!inv.lexware)return '';const link=String(inv.lexware_deeplink||'');return `<span class="lexware-badge" ${link?`data-lexware-link="${escapeHtml(link)}" title="In Lexware Office öffnen"`: 'title="In Lexware Office vorhanden"'}><img src="${LEXWARE_LOGO_URL}" alt="Lexware Office" onerror="this.style.display='none';this.nextElementSibling.style.display='inline'"/><span class="lexware-text">Lexware</span></span>`}
function financePartyName(inv={}){return inv.direction==='supplier'?(inv.supplier_name||inv.customer_name||'Lieferant'):(inv.customer_name||inv.supplier_name||'Kunde')}
function financeDisplayNo(inv={}){if(inv.direction==='customer'&&inv.status==='draft'&&String(inv.invoice_no||'').startsWith('DRAFT-'))return 'Entwurf';return inv.direction==='supplier'?(inv.external_invoice_no||inv.invoice_no||''):(inv.invoice_no||'')}
function financeOpenAmount(inv={}){if(inv.lexware_open_amount===null||inv.lexware_open_amount===undefined||inv.lexware_open_amount==='')return '';return Number(inv.lexware_open_amount)||0}
async function loadFinanceInvoices(){
  if(!productionServerConfigured())return;const host=$('#financeInvoiceList');if(!host)return;host.innerHTML='<div class="business-loading">Rechnungen werden geladen …</div>';
  const q=String($('#financeInvoiceSearch')?.value||'').trim();
  try{const d=await businessApi(`/finance/invoices?q=${encodeURIComponent(q)}&direction=${encodeURIComponent(financeInvoiceDirection)}&status=${encodeURIComponent(financeInvoiceStatus)}&limit=2000`);financeInvoiceCache=d.items||[];financeLexwareSettings=d.lexware||financeLexwareSettings;renderFinanceInvoiceList();const open=financeInvoiceCache.filter(x=>!['paid','paidoff','voided','cancelled'].includes(String(x.status||''))&&String(x.payment_status||'')!=='paid').length;if($('#invoicesBadge'))$('#invoicesBadge').textContent=open;if($('#dashboardInvoices'))$('#dashboardInvoices').textContent=open;}catch(err){host.innerHTML=`<div class="business-empty error">Rechnungen konnten nicht geladen werden: ${escapeHtml(err.message||String(err))}</div>`}
}
function renderFinanceInvoiceList(){const host=$('#financeInvoiceList');if(!host)return;const rows=financeInvoiceCache;if(!rows.length){host.innerHTML='<div class="business-empty"><b>Noch keine passenden Rechnungen.</b><span>Erstelle eine Kundenrechnung oder erfasse eine Lieferantenrechnung. Nach der Lexware-Synchronisierung erscheinen hier auch externe Belege.</span></div>';return}host.innerHTML=`<div class="finance-list-head"><span>Rechnung</span><span>Kunde / Lieferant</span><span>Quelle</span><span>Datum</span><span>Status</span><span>Brutto</span><span>Lexware</span><span></span></div>${rows.map(x=>`<button class="finance-list-row" data-finance-invoice="${escapeHtml(x.id)}"><span class="business-main-cell"><b>${escapeHtml(financeDisplayNo(x))}</b><small>${escapeHtml(x.direction==='supplier'&&x.invoice_no&&x.external_invoice_no?`HCA ${x.invoice_no}`:(x.subject||''))}</small></span><span>${escapeHtml(financePartyName(x))}</span><span>${financeSourceLabel(x)}</span><span>${businessDate(x.invoice_date)}</span><span>${financeInvoiceStatusPill(x)}${financeOpenAmount(x)!==''&&x.lexware?`<small class="finance-open-amount">offen ${businessMoney(financeOpenAmount(x))}</small>`:''}</span><span><b>${businessMoney(x.total_gross)}</b></span><span>${lexwareBadge(x)||'–'}</span><span class="business-row-arrow">›</span></button>`).join('')}`;host.querySelectorAll('[data-finance-invoice]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-lexware-link]'))return;openFinanceInvoice(b.dataset.financeInvoice)});host.querySelectorAll('[data-lexware-link]').forEach(b=>b.onclick=e=>{e.stopPropagation();window.open(b.dataset.lexwareLink,'_blank','noopener')});}
async function openFinanceInvoice(id){activeFinanceInvoiceId=String(id||'');businessOpenView('invoices');$('#financeCustomerInvoiceEditorPage')?.classList.add('hidden');$('#financeSupplierInvoiceEditorPage')?.classList.add('hidden');$('#financeInvoiceListPage')?.classList.add('hidden');$('#financeInvoiceDetailPage')?.classList.remove('hidden');const host=$('#financeInvoiceDetail');if(host)host.innerHTML='<div class="business-loading">Rechnung wird geladen …</div>';try{const d=await businessApi(`/finance/invoices/${encodeURIComponent(activeFinanceInvoiceId)}`);activeFinanceInvoice=d.item||{};renderFinanceInvoiceDetail(activeFinanceInvoice)}catch(err){if(host)host.innerHTML=`<div class="business-empty error">${escapeHtml(err.message||String(err))}</div>`}}
function financeAddressBlock(a={}){return [a.name||a.company_name,a.attention,a.street,[a.zip,a.city].filter(Boolean).join(' '),a.country].filter(Boolean).map(escapeHtml).join('<br>')||'–'}
function renderFinanceInvoiceDetail(inv={}){const host=$('#financeInvoiceDetail'),actions=$('#financeInvoiceTopActions');if(!host)return;const external=inv.record_type==='external';const displayNo=financeDisplayNo(inv);let buttons='';if(!external&&inv.direction==='customer'&&inv.status==='draft')buttons+='<button class="btn primary" id="financeFinalizeInvoice" type="button">Festschreiben</button>';if(!external&&inv.direction==='customer')buttons+='<button class="btn secondary" id="financePrintInvoice" type="button">Drucken / PDF</button>';if(!external&&inv.has_file)buttons+='<button class="btn secondary" id="financeDownloadFile" type="button">Originalbeleg</button>';if(!external&&!inv.lexware&&!(inv.direction==='customer'&&inv.status==='draft'))buttons+='<button class="btn primary" id="financeSendLexware" type="button">An Lexware übertragen</button>';if(inv.lexware&&inv.lexware_deeplink)buttons+=`<button class="btn secondary lexware-action" id="financeOpenLexware" type="button">${lexwareBadge(inv)} Öffnen</button>`;if(actions)actions.innerHTML=buttons;const items=inv.items||[];host.innerHTML=`<div class="business-object-head"><div><div class="eyebrow">${inv.direction==='supplier'?'LIEFERANTENRECHNUNG':'KUNDENRECHNUNG'} · ${escapeHtml(displayNo||'')}</div><h2>${escapeHtml(inv.subject||financePartyName(inv)||'Rechnung')}</h2><div class="business-object-meta">${escapeHtml(financePartyName(inv))} · ${businessDate(inv.invoice_date)}${inv.source==='woocommerce'?' · WooCommerce':''}</div></div><div class="finance-object-status">${financeInvoiceStatusPill(inv)}${lexwareBadge(inv)}</div></div><div class="business-two-col"><div class="panel"><div class="panel-head"><div><h3>Rechnungsdaten</h3></div></div><div class="business-kv"><span>Rechnungsnummer</span><b>${escapeHtml(displayNo||'–')}</b>${inv.direction==='supplier'?`<span>Interne Nummer</span><b>${escapeHtml(inv.invoice_no||'–')}</b>`:''}<span>Datum</span><b>${businessDate(inv.invoice_date)}</b><span>Fällig</span><b>${businessDate(inv.due_date)}</b><span>Status</span><b>${escapeHtml(FINANCE_STATUS_LABELS[inv.status]||inv.status||'–')}</b><span>Quelle</span><b>${inv.source==='woocommerce'?'WooCommerce':inv.source==='lexware_external'?'Lexware Office':'HCA'}</b>${inv.sales_order_id?`<span>Auftrag</span><b><button class="business-link-button" data-finance-order="${escapeHtml(inv.sales_order_id)}">Auftrag öffnen</button></b>`:''}${inv.purchase_reference?`<span>Bestellreferenz</span><b>${escapeHtml(inv.purchase_reference)}</b>`:''}</div></div><div class="panel"><div class="panel-head"><div><h3>Summe</h3></div></div><div class="business-totals static"><div><span>Netto</span><strong>${businessMoney(inv.total_net)}</strong></div><div><span>MwSt.</span><strong>${businessMoney(inv.total_tax)}</strong></div><div class="grand"><span>Brutto</span><strong>${businessMoney(inv.total_gross)}</strong></div>${inv.lexware&&financeOpenAmount(inv)!==''?`<div><span>In Lexware offen</span><strong>${businessMoney(financeOpenAmount(inv))}</strong></div>`:''}</div></div></div>${inv.direction==='customer'&&!external?`<div class="business-two-col"><div class="panel"><div class="eyebrow">RECHNUNGSADRESSE</div><p>${financeAddressBlock(inv.billing||{})}</p></div><div class="panel"><div class="eyebrow">LIEFERADRESSE</div><p>${financeAddressBlock(inv.shipping||{})}</p></div></div>`:''}${items.length?`<div class="panel"><div class="panel-head"><div><h3>Positionen</h3></div></div><div class="business-position-table finance-items"><div class="head"><span>Pos.</span><span>Beschreibung</span><span>Menge</span><span>Einzel netto</span><span>MwSt.</span><span>Brutto</span></div>${items.map((x,i)=>`<div class="row"><span>${i+1}</span><span><b>${escapeHtml(x.description||'')}</b><small>${escapeHtml(x.sku||'')}</small></span><span>${Number(x.quantity)||0} ${escapeHtml(x.unit||'')}</span><span>${businessMoney(x.unit_price)}</span><span>${Number(x.tax_rate)||0}%</span><span><b>${businessMoney(x.gross_total)}</b></span></div>`).join('')}</div></div>`:external?'<div class="panel"><div class="business-empty compact">Dieser Beleg stammt aus Lexware Office. Positionsdaten werden in dieser ersten Synchronisationsstufe nicht importiert. Über „Öffnen“ gelangst du zum Originalbeleg in Lexware.</div></div>':''}${inv.notes?`<div class="panel"><div class="eyebrow">NOTIZ</div><p class="business-note">${escapeHtml(inv.notes)}</p></div>`:''}`;$('#financeFinalizeInvoice')?.addEventListener('click',()=>finalizeFinanceInvoice(inv.id));$('#financePrintInvoice')?.addEventListener('click',()=>printFinanceInvoice(inv));$('#financeDownloadFile')?.addEventListener('click',()=>downloadFinanceFile(inv));$('#financeSendLexware')?.addEventListener('click',()=>sendFinanceInvoiceToLexware(inv.id));$('#financeOpenLexware')?.addEventListener('click',()=>window.open(inv.lexware_deeplink,'_blank','noopener'));host.querySelectorAll('[data-finance-order]').forEach(b=>b.onclick=()=>openBusinessSalesOrder(b.dataset.financeOrder,'invoices'))}
async function createFinanceInvoiceFromOrder(orderId){if(!orderId)return;try{const d=await businessApi(`/finance/invoices/from-order/${encodeURIComponent(orderId)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});await Promise.all([loadFinanceInvoices(),loadBusinessDashboard()]);if(d.already_exists)alert('Zu diesem Auftrag existiert bereits eine Rechnung. Sie wird jetzt geöffnet.');await openFinanceInvoice(d.item.id)}catch(err){alert(`Rechnung konnte nicht erstellt werden:\n${err.message||err}`)}}
function financeNewLine(v={}){return newBusinessQuoteLine({...v,item_type:v.item_type||'product',unit:v.unit||'Stk.'})}
function mountBusinessMainEditors(){
  const mounts=[['businessSalesOrderDialog','businessSalesOrderEditorHost'],['financeCustomerInvoiceDialog','financeCustomerInvoiceEditorHost'],['financeSupplierInvoiceDialog','financeSupplierInvoiceEditorHost']];
  mounts.forEach(([editor,host])=>{const node=$(`#${editor}`),target=$(`#${host}`);if(node&&target&&node.parentElement!==target)target.appendChild(node)});
}
function closeBusinessSalesOrderEditor(){
  $('#businessSalesOrderEditorPage')?.classList.add('hidden');$('#businessSalesOrderDetailPage')?.classList.add('hidden');$('#businessSalesOrderListPage')?.classList.remove('hidden');activeBusinessSalesOrderId='';loadBusinessSalesOrders();
}
function showFinanceEntryPage(kind){
  businessOpenView('invoices');$('#financeInvoiceListPage')?.classList.add('hidden');$('#financeInvoiceDetailPage')?.classList.add('hidden');$('#financeCustomerInvoiceEditorPage')?.classList.toggle('hidden',kind!=='customer');$('#financeSupplierInvoiceEditorPage')?.classList.toggle('hidden',kind!=='supplier');
}
function closeFinanceEntryPage(){
  $('#financeCustomerInvoiceEditorPage')?.classList.add('hidden');$('#financeSupplierInvoiceEditorPage')?.classList.add('hidden');$('#financeInvoiceDetailPage')?.classList.add('hidden');$('#financeInvoiceListPage')?.classList.remove('hidden');activeFinanceInvoiceId='';activeFinanceInvoice=null;loadFinanceInvoices();
}
mountBusinessMainEditors();
async function openFinanceCustomerInvoiceDialog(customerId=''){await ensureBusinessCustomers();financeInvoiceLines=[financeNewLine()];$('#financeInvoiceCustomer').innerHTML=businessCustomerOptions(customerId||businessDefaultCustomerId);$('#financeInvoiceCustomer').value=customerId||businessDefaultCustomerId||'';$('#financeInvoiceSubject').value='Rechnung';$('#financeInvoiceDate').value=financeToday();$('#financeInvoiceDue').value=financeDatePlus(14);$('#financeInvoiceReference').value='';$('#financeInvoiceNotes').value='';renderFinanceInvoiceLines();showFinanceEntryPage('customer')}
function renderFinanceInvoiceLines(){const host=$('#financeInvoiceLines');if(!host)return;host.innerHTML=financeInvoiceLines.map((x,i)=>`<div class="finance-line-row" data-finance-line="${escapeHtml(x.id)}"><span class="finance-line-pos">${i+1}</span><input class="text-input" data-fline="description" value="${escapeHtml(x.description)}" placeholder="Artikel / Leistung"><input class="text-input finance-small" data-fline="quantity" type="number" min="0.01" step="0.01" value="${x.quantity}"><input class="text-input finance-small" data-fline="unit" value="${escapeHtml(x.unit)}"><input class="text-input finance-money" data-fline="unit_price" type="number" step="0.01" value="${x.unit_price}"><input class="text-input finance-small" data-fline="tax_rate" type="number" step="0.01" value="${x.tax_rate}"><button class="business-mini-action danger" type="button" data-remove-fline="${escapeHtml(x.id)}">×</button></div>`).join('');host.querySelectorAll('[data-finance-line]').forEach(row=>row.querySelectorAll('[data-fline]').forEach(inp=>inp.addEventListener('input',()=>{const line=financeInvoiceLines.find(x=>x.id===row.dataset.financeLine);if(!line)return;const k=inp.dataset.fline;line[k]=['quantity','unit_price','tax_rate'].includes(k)?Number(inp.value||0):inp.value})));host.querySelectorAll('[data-remove-fline]').forEach(b=>b.onclick=()=>{if(financeInvoiceLines.length<=1){financeInvoiceLines=[financeNewLine()]}else financeInvoiceLines=financeInvoiceLines.filter(x=>x.id!==b.dataset.removeFline);renderFinanceInvoiceLines()})}
async function saveFinanceCustomerInvoice(){const customer=$('#financeInvoiceCustomer').value;if(!customer){alert('Bitte einen Kunden auswählen.');return}if(!financeInvoiceLines.some(x=>x.description.trim())){alert('Bitte mindestens eine Rechnungsposition anlegen.');return}if(financeInvoiceLines.some(x=>Array.isArray(x.config?.available_colors)&&x.config.available_colors.length&&!x.config.color)){alert('Bitte bei jeder gefundenen Ware eine Farbe auswählen.');return}const payload={direction:'customer',customer_id:customer,subject:$('#financeInvoiceSubject').value.trim()||'Rechnung',invoice_date:$('#financeInvoiceDate').value,due_date:$('#financeInvoiceDue').value,customer_reference:$('#financeInvoiceReference').value.trim(),notes:$('#financeInvoiceNotes').value.trim(),items:financeInvoiceLines.filter(x=>x.description.trim())};try{const d=await businessApi('/finance/invoices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#financeCustomerInvoiceEditorPage')?.classList.add('hidden');await Promise.all([loadFinanceInvoices(),loadBusinessDashboard()]);await openFinanceInvoice(d.item.id)}catch(err){alert(`Kundenrechnung konnte nicht angelegt werden:\n${err.message||err}`)}}
function openFinanceSupplierInvoiceDialog(){const today=financeToday();$('#financeSupplierName').value='';$('#financeSupplierInvoiceNo').value='';$('#financeSupplierPurchaseRef').value='';$('#financeSupplierSubject').value='Lieferantenrechnung';$('#financeSupplierDate').value=today;$('#financeSupplierDue').value=financeDatePlus(14);$('#financeSupplierNet').value='';$('#financeSupplierTax').value='';$('#financeSupplierGross').value='';$('#financeSupplierTaxRate').value='19';$('#financeSupplierFile').value='';$('#financeSupplierNotes').value='';showFinanceEntryPage('supplier')}
function financeFileData(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);const r=new FileReader();r.onload=()=>resolve({name:file.name,mime:file.type||'',data:String(r.result||'')});r.onerror=()=>reject(new Error('Belegdatei konnte nicht gelesen werden.'));r.readAsDataURL(file)})}
async function saveFinanceSupplierInvoice(){const supplier=$('#financeSupplierName').value.trim(),external=$('#financeSupplierInvoiceNo').value.trim();if(!supplier||!external){alert('Bitte Lieferant und Rechnungsnummer des Lieferanten angeben.');return}const net=Number($('#financeSupplierNet').value||0),tax=Number($('#financeSupplierTax').value||0),gross=Number($('#financeSupplierGross').value||0);if(gross<=0){alert('Bitte den Bruttobetrag der Lieferantenrechnung angeben.');return}try{const attachment=await financeFileData($('#financeSupplierFile').files?.[0]);const payload={direction:'supplier',supplier_name:supplier,external_invoice_no:external,purchase_reference:$('#financeSupplierPurchaseRef').value.trim(),subject:$('#financeSupplierSubject').value.trim()||'Lieferantenrechnung',invoice_date:$('#financeSupplierDate').value,due_date:$('#financeSupplierDue').value,total_net:net,total_tax:tax,total_gross:gross,tax_rate:Number($('#financeSupplierTaxRate').value||19),notes:$('#financeSupplierNotes').value.trim(),attachment};const d=await businessApi('/finance/invoices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),timeoutMs:60000});$('#financeSupplierInvoiceEditorPage')?.classList.add('hidden');await loadFinanceInvoices();await openFinanceInvoice(d.item.id)}catch(err){alert(`Lieferantenrechnung konnte nicht gespeichert werden:\n${err.message||err}`)}}
async function finalizeFinanceInvoice(id){if(!await hcaConfirm('Rechnung festschreiben? Danach kann sie nicht mehr wie ein Entwurf geändert werden.'))return;try{const d=await businessApi(`/finance/invoices/${encodeURIComponent(id)}/finalize`,{method:'POST'});activeFinanceInvoice=d.item;renderFinanceInvoiceDetail(d.item);await Promise.all([loadFinanceInvoices(),loadBusinessDashboard()])}catch(err){alert(`Rechnung konnte nicht festgeschrieben werden:\n${err.message||err}`)}}
async function sendFinanceInvoiceToLexware(id){if(!await hcaConfirm('Diesen Beleg jetzt an Lexware Office übertragen?'))return;try{const d=await businessApi(`/finance/invoices/${encodeURIComponent(id)}/lexware`,{method:'POST',timeoutMs:60000});activeFinanceInvoice=d.item;renderFinanceInvoiceDetail(d.item);await loadFinanceInvoices()}catch(err){alert(`Lexware-Übertragung fehlgeschlagen:\n${err.message||err}`)}}
async function syncLexwareInvoices(showMessage=true){const btn=$('#syncLexwareInvoices');if(btn)btn.disabled=true;try{const d=await businessApi('/finance/lexware/sync',{method:'POST',timeoutMs:90000});await Promise.all([loadFinanceInvoices(),loadBusinessDashboard(),loadLexwareSettings()]);if(showMessage)alert(`${Number(d.count)||0} Lexware-Belege wurden synchronisiert.`)}catch(err){if(showMessage)alert(`Lexware-Synchronisierung fehlgeschlagen:\n${err.message||err}`)}finally{if(btn)btn.disabled=false}}
async function downloadFinanceFile(inv){try{const res=await productionFetch(`/api/hca-shared/finance/invoices/${encodeURIComponent(inv.id)}/file`,{timeoutMs:30000});if(!res.ok)throw new Error(`HTTP ${res.status}`);const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=inv.file_name||'beleg';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){alert(`Beleg konnte nicht geladen werden:\n${err.message||err}`)}}
function printFinanceInvoice(inv){const w=window.open('','_blank','width=980,height=900');if(!w){alert('Druckfenster wurde vom Browser blockiert.');return}const logo=new URL('/assets/logo-app.png',location.href).href,items=inv.items||[],issuer=[appState.settings?.labelCompany,appState.settings?.labelAddress,appState.settings?.labelCity,appState.settings?.labelCountry,appState.settings?.labelContact].filter(Boolean).map(escapeHtml).join(' · ');w.document.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${escapeHtml(inv.invoice_no||'Rechnung')}</title><style>body{font-family:Arial,sans-serif;color:#161616;margin:32px 46px;font-size:13px}header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #e75303;padding-bottom:18px;margin-bottom:28px}header img{max-width:240px;max-height:75px}.right{text-align:right}h1{font-size:28px;margin:0 0 8px}.address{margin:34px 0;line-height:1.55}.meta{display:grid;grid-template-columns:140px 1fr;gap:5px 12px;max-width:440px;margin-left:auto}.meta span{color:#666}table{width:100%;border-collapse:collapse;margin-top:28px}th{text-align:left;border-bottom:2px solid #222;padding:8px 5px;font-size:12px}td{padding:9px 5px;border-bottom:1px solid #ddd;vertical-align:top}.num{text-align:right}.totals{margin:22px 0 0 auto;width:330px}.totals div{display:flex;justify-content:space-between;padding:5px}.totals .grand{font-size:17px;font-weight:bold;border-top:2px solid #222;margin-top:5px;padding-top:9px}footer{margin-top:55px;border-top:1px solid #ddd;padding-top:14px;color:#666;font-size:11px}@media print{body{margin:12mm}button{display:none}}</style></head><body><header><img src="${logo}" alt="Werbestudio Königswinter"><div class="right"><h1>Rechnung</h1><b>${escapeHtml(inv.invoice_no||'')}</b></div></header><div class="address">${financeAddressBlock(inv.billing||{})}</div><div class="meta"><span>Rechnungsdatum</span><b>${businessDate(inv.invoice_date)}</b><span>Fällig am</span><b>${businessDate(inv.due_date)}</b>${inv.customer_reference?`<span>Ihre Referenz</span><b>${escapeHtml(inv.customer_reference)}</b>`:''}</div><h2>${escapeHtml(inv.subject||'Rechnung')}</h2><table><thead><tr><th>Pos.</th><th>Beschreibung</th><th class="num">Menge</th><th class="num">Einzel netto</th><th class="num">MwSt.</th><th class="num">Gesamt</th></tr></thead><tbody>${items.map((x,i)=>`<tr><td>${i+1}</td><td><b>${escapeHtml(x.description||'')}</b>${x.sku?`<br><small>${escapeHtml(x.sku)}</small>`:''}</td><td class="num">${Number(x.quantity)||0} ${escapeHtml(x.unit||'')}</td><td class="num">${businessMoney(x.unit_price)}</td><td class="num">${Number(x.tax_rate)||0}%</td><td class="num">${businessMoney(x.gross_total)}</td></tr>`).join('')}</tbody></table><div class="totals"><div><span>Netto</span><b>${businessMoney(inv.total_net)}</b></div><div><span>MwSt.</span><b>${businessMoney(inv.total_tax)}</b></div><div class="grand"><span>Brutto</span><b>${businessMoney(inv.total_gross)}</b></div></div>${inv.notes?`<p>${escapeHtml(inv.notes)}</p>`:''}<footer>${issuer||'Werbestudio Königswinter'}<br>Erstellt mit HCA Manager</footer><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close()}
async function loadLexwareSettings(){if(!productionServerConfigured())return;const st=$('#lexwareSettingsStatus');try{const d=await businessApi('/finance/lexware/settings');financeLexwareSettings=d;if($('#lexwareApiToken')){$('#lexwareApiToken').value='';$('#lexwareApiToken').placeholder=d.configured?`gespeichert ${d.token_hint||''}`:'API-Schlüssel einfügen'}if(st)st.textContent=d.configured?`Verbunden${d.last_sync?` · Sync ${businessDate(d.last_sync)}`:''}`:'Noch nicht konfiguriert';if(d.configured)await loadLexwareCategories(false)}catch(err){if(st)st.textContent='Lexware-Status nicht verfügbar'}}
async function loadLexwareCategories(showError=true){try{const d=await businessApi('/finance/lexware/posting-categories',{timeoutMs:45000}),items=d.items||[],settings=financeLexwareSettings||{};const opts='<option value="">Kategorie auswählen …</option>'+items.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name||x.id)}</option>`).join('');const s=$('#lexwareSalesCategory'),p=$('#lexwarePurchaseCategory');if(s){s.innerHTML=opts;s.value=settings.sales_category_id||''}if(p){p.innerHTML=opts;p.value=settings.purchase_category_id||''}}catch(err){if(showError)alert(`Lexware-Kategorien konnten nicht geladen werden:\n${err.message||err}`)}}
async function saveLexwareSettings(){const sales=$('#lexwareSalesCategory'),purchase=$('#lexwarePurchaseCategory'),payload={sales_category_id:sales?.value||'',sales_category_name:sales?.selectedOptions?.[0]?.textContent||'',purchase_category_id:purchase?.value||'',purchase_category_name:purchase?.selectedOptions?.[0]?.textContent||''};const token=$('#lexwareApiToken')?.value.trim();if(token)payload.token=token;try{const d=await businessApi('/finance/lexware/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});financeLexwareSettings=d;$('#lexwareApiToken').value='';$('#lexwareApiToken').placeholder=d.configured?`gespeichert ${d.token_hint||''}`:'API-Schlüssel einfügen';$('#lexwareSettingsStatus').textContent=d.configured?'Lexware gespeichert':'Noch nicht konfiguriert';alert('Lexware-Einstellungen wurden zentral auf der Synology gespeichert.')}catch(err){alert(`Lexware-Einstellungen konnten nicht gespeichert werden:\n${err.message||err}`)}}
async function testLexwareSettings(){const token=$('#lexwareApiToken')?.value.trim();if(token)await saveLexwareSettings();const st=$('#lexwareSettingsStatus');if(st)st.textContent='Lexware wird geprüft …';try{const d=await businessApi('/finance/lexware/test',{method:'POST',timeoutMs:45000});if(st)st.textContent=d.message||'Lexware Office erreichbar';await loadLexwareSettings();await loadLexwareCategories(true)}catch(err){if(st)st.textContent='Verbindung fehlgeschlagen';alert(`Lexware-Verbindung fehlgeschlagen:\n${err.message||err}`)}}

