const HCA_VIEW_CATEGORY={dashboard:'start',customers:'crm',suppliers:'crm',mail:'mail',quotes:'commerce',salesorders:'commerce',invoices:'finance',deliverynotes:'logistics',inventory:'logistics',shipping:'logistics',production:'production',orders:'production',workbench:'production',transfer:'production',machines:'production',logview:'system',settings:'system',help:'system'};
let activeHcaCategory='start';
function setHcaMainCategory(category,preferredView=''){activeHcaCategory=category||'start';$$('.main-category').forEach(b=>b.classList.toggle('active',b.dataset.category===activeHcaCategory));$$('.nav-item').forEach(b=>b.classList.toggle('category-hidden',b.dataset.category!==activeHcaCategory));if(preferredView){const target=$(`.nav-item[data-view="${preferredView}"]`);if(target&&!target.classList.contains('category-hidden'))return} }
$$('.main-category').forEach(b=>b.addEventListener('click',()=>{const cat=b.dataset.category;setHcaMainCategory(cat);const first=$(`.nav-item[data-category="${cat}"]:not(.hidden)`);if(first){if(first.dataset.view==='transfer')openTransferWorkflow(null);else showView(first.dataset.view,cat,first.dataset.inventoryTarget||'')}}));

const viewTitles={dashboard:'Dashboard',customers:'Kunden',suppliers:'Lieferanten',mail:'E-Mail',quotes:'Angebote',salesorders:'Aufträge',invoices:'Rechnungen',deliverynotes:'Lieferscheine',transfer:'Stickdatei übertragen',production:'Produktionsmonitor',orders:'Produktionsaufträge',inventory:'Einkauf & Lager',workbench:'Arbeitsplatz',shipping:'Versand',machines:'Maschinen',logview:'Protokoll',settings:'Einstellungen',help:'Hilfe & Workflow'};
function showView(name,categoryOverride='',inventoryTarget=''){
  setHcaMainCategory(categoryOverride||HCA_VIEW_CATEGORY[name]||activeHcaCategory,name);
  $$('.view').forEach(v=>v.classList.remove('active'));$(`#view-${name}`)?.classList.add('active');
  const navView=name;
  $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===navView));$('#viewTitle').textContent=viewTitles[name]||'';
  if(name==='dashboard')loadBusinessDashboard();if(name==='customers'){if(!activeBusinessCustomerId){$('#crmCustomerDetailPage')?.classList.add('hidden');$('#crmCustomerListPage')?.classList.remove('hidden');loadBusinessCustomers();}}if(name==='quotes'){if(!activeBusinessQuote){$('#businessQuoteEditorPage')?.classList.add('hidden');$('#businessQuoteListPage')?.classList.remove('hidden');loadBusinessQuotes();}}if(name==='salesorders'){if(!activeBusinessSalesOrderId){$('#businessSalesOrderEditorPage')?.classList.add('hidden');$('#businessSalesOrderDetailPage')?.classList.add('hidden');$('#businessSalesOrderListPage')?.classList.remove('hidden');loadBusinessSalesOrders();}}if(name==='invoices'){if(!activeFinanceInvoiceId){$('#financeCustomerInvoiceEditorPage')?.classList.add('hidden');$('#financeSupplierInvoiceEditorPage')?.classList.add('hidden');$('#financeInvoiceDetailPage')?.classList.add('hidden');$('#financeInvoiceListPage')?.classList.remove('hidden');loadFinanceInvoices();}}if(name==='deliverynotes'){closeDeliveryNoteDetail(false);loadDeliveryNotes();}if(name==='production'){if(centralProductionMonitorOrder)renderCentralProductionMonitor();else renderProduction();}if(name==='machines')renderInventory();if(name==='orders'){loadCentralOrders();loadWooStatus();}if(name==='inventory'){if(inventoryTarget)showInventoryModule(inventoryTarget);else if(inventoryModule==='warehouses')showInventoryModule('warehouses');else if(inventoryModule==='receipts')showInventoryModule('receipts');else{showInventoryListPage(true);loadInventory();}}if(name==='workbench')loadWorkbench();if(name==='shipping')loadShippingGroups();if(name==='settings'&&sharedServerReady){loadCentralCareProfiles(false);loadCentralThreadCatalogs(true);loadLexwareSettings();}
}
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>{
  if(b.dataset.view==='transfer')openTransferWorkflow(null);
  else showView(b.dataset.view,b.dataset.category||'',b.dataset.inventoryTarget||'');
}));

function renderConnectionSummary(){
  $$('.connection-indicator[data-connection-machine]').forEach(el=>{
    const i=Number(el.dataset.connectionMachine),m=machines[i];
    el.classList.toggle('online',!!m?.connected);
    const label=el.querySelector('span:last-child');
    if(label)label.textContent=m?.name||`HCA ${i+1}`;
    el.title=m?.kind==='pico'
      ?(m.connected?'Pico / HCA 4 erreichbar':'Pico / HCA 4 nicht erreichbar')
      :(m.connected?`${m.serialPort||''} verbunden`:(m.serialError||`${m.serialPort||'Kein COM-Port'} nicht verbunden`));
  });
}
function renderTransferMachineButtons(){
  const host=$('#transferMachineButtons');if(!host)return;
  if(!transferSelectionInitialized){const first=machines.find(m=>m.connected);if(first){selectedTransferMachines.add(first.index);transferSelectionInitialized=true;}}
  host.innerHTML=machines.map(m=>{const selected=selectedTransferMachines.has(m.index),online=!!m.connected;return `<button type="button" class="transfer-machine-btn ${selected?'selected':''} ${online?'online':'offline'}" data-transfer-machine="${m.index}" ${online?'':'disabled'} aria-pressed="${selected?'true':'false'}"><span class="transfer-machine-dot"></span><strong>${escapeHtml(m.name)}</strong><small>${online?(m.kind==='pico'?'Pico':escapeHtml(m.serialPort||'verbunden')):'nicht verbunden'}</small></button>`;}).join('');
  host.querySelectorAll('[data-transfer-machine]').forEach(btn=>btn.addEventListener('click',()=>{const i=Number(btn.dataset.transferMachine);if(!machines[i]?.connected)return;if(selectedTransferMachines.has(i))selectedTransferMachines.delete(i);else selectedTransferMachines.add(i);log(`${machines[i].name}: Übertragung ${selectedTransferMachines.has(i)?'ausgewählt':'abgewählt'}.`);renderTransferMachineButtons();updateButtons();renderMachineTransferPlans();}));
}
function renderMachines(){
  renderConnectionSummary();renderTransferMachineButtons();updateButtons();updateGlobalStatus();renderMachineTransferPlans();
}

let serialStatusBusy=false;
async function refreshSerialStatus(){
  if(serialStatusBusy)return;
  serialStatusBusy=true;
  try{
    const res=await fetch('/api/serial/status',{cache:'no-store'});
    const data=await res.json();
    if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);
    (Array.isArray(data.items)?data.items:[]).slice(0,3).forEach((item,i)=>{
      const m=machines[i],was=!!m.connected;
      m.serialPort=String(item.port||'');
      m.serialError=String(item.error||'');
      m.connected=!!item.connected;
      if(was!==m.connected){
        if(m.connected)log(`${m.name}: ${m.serialPort} automatisch verbunden.`);
        else if(was)log(`${m.name}: COM-Verbindung getrennt${m.serialError?`: ${m.serialError}`:''}.`);
      }
    });
    const st=$('#serialSettingsStatus');
    if(st){
      const labels=machines.slice(0,3).map(m=>`${m.name}: ${m.serialPort||'–'} ${m.connected?'✓':'✕'}`);
      st.textContent=labels.join(' · ');
    }
    renderMachines();
  }catch(err){
    const st=$('#serialSettingsStatus');if(st)st.textContent=`COM-Status konnte nicht gelesen werden: ${err.message||err}`;
  }finally{serialStatusBusy=false;}
}

async function toggleConnect(index){
  const m=machines[index];if(m.kind==='pico')return checkPicoConnection(true);if(m.connected)return disconnectMachine(index);
  if(!('serial'in navigator)){alert('Web Serial ist nicht verfügbar. Bitte Microsoft Edge oder Google Chrome verwenden.');return;}
  try{log(`${m.name}: Geräteauswahl wird geöffnet …`);const port=await navigator.serial.requestPort();await port.open(SERIAL_OPTIONS);m.port=port;m.connected=true;m.rx=[];log(`${m.name}: RS232 verbunden (38400 / 8N1 / Flow-Control aus).`);startReader(m);renderMachines();}
  catch(err){log(`${m.name}: Verbindung fehlgeschlagen: ${err.message||err}`);}
}
async function disconnectMachine(index){const m=machines[index];try{m.reading=false;if(m.reader){try{await m.reader.cancel();}catch{}try{m.reader.releaseLock();}catch{}m.reader=null;}if(m.port){try{await m.port.close();}catch{}}}finally{m.port=null;m.connected=false;log(`${m.name}: getrennt.`);renderMachines();}}
async function startReader(m){if(!m.port?.readable||m.reading)return;m.reading=true;while(m.port?.readable&&m.reading){const reader=m.port.readable.getReader();m.reader=reader;try{while(m.reading){const{value,done}=await reader.read();if(done)break;if(value?.length){m.rx.push(...Array.from(value));if(m.rx.length>65536)m.rx.splice(0,m.rx.length-65536);log(`${m.name} RX ${value.length} B: ${hex(value)}`);}}}catch(err){if(m.reading)log(`${m.name}: Lesefehler: ${err.message||err}`);}finally{try{reader.releaseLock();}catch{}if(m.reader===reader)m.reader=null;}break;}m.reading=false;}

function setSelectedFile(info){selectedFile=info;renderSelectedFile();cacheSelectedMotifForLabels(info);log(`Datei ausgewählt: ${info.name} (${info.size} Byte)`);updateButtons();updateGlobalStatus();if(info.nasPath)autoLoadHp1ForSelectedFile(info);}
$('#localFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;setSelectedFile({name:f.name,size:f.size,bytes:new Uint8Array(await f.arrayBuffer())});});

