  try{const res=await fetch('/api/list?path='+encodeURIComponent(path),{cache:'no-store'});const data=await res.json();if(!res.ok)throw new Error(data.error||'Fehler');nasParent=data.parent||'';nasItems=data.items||[];renderNasItems();}
  catch(err){$('#nasList').innerHTML=`<div class="entry"><span>!</span><span class="name">${escapeHtml(err.message||String(err))}</span></div>`;}
