function renderNasItems(){const q=$('#fileSearch').value.trim().toLowerCase();const list=$('#nasList');list.innerHTML='';const items=nasItems.filter(x=>(x.type==='dir'||/\.(tap|dst)$/i.test(x.name))&&(!q||x.name.toLowerCase().includes(q)));if(!items.length){list.innerHTML='<div class="entry"><span></span><span class="name">Keine passenden Stickdateien</span></div>';return;}for(const item of items){const row=document.createElement('div');row.className='entry';row.innerHTML=`<span>${item.type==='dir'?'📁':'🧵'}</span><span class="name">${escapeHtml(item.name)}</span><span class="size">${item.type==='file'?fmtBytes(item.size):''}</span>`;row.addEventListener('click',()=>item.type==='dir'?loadNas(item.path):selectNasFile(item));list.appendChild(row);}}
async function selectNasFile(item){try{const res=await fetch('/api/file?path='+encodeURIComponent(item.path),{cache:'no-store'});if(!res.ok)throw new Error('Datei konnte nicht geladen werden');const bytes=new Uint8Array(await res.arrayBuffer());setSelectedFile({name:item.name,size:bytes.length,bytes,nasPath:item.path});}catch(err){log(`Synology-Datei konnte nicht geladen werden: ${err.message||err}`);}}
$('#nasUp').addEventListener('click',()=>loadNas(nasParent));$('#nasReload').addEventListener('click',()=>loadNas(currentNasPath));$('#fileSearch').addEventListener('input',renderNasItems);
$('#hp1File').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(!selectedFile)throw new Error('Bitte zuerst ein TAP- oder DST-Motiv auswählen.');applyNeedleInfo(parseHp1(new Uint8Array(await f.arrayBuffer()),f.name),'hp1-file');}catch(err){alert(`HP1 konnte nicht übernommen werden: ${err.message||err}`);log(`HP1-Fehler: ${err.message||err}`);}finally{e.target.value='';}});

function updateButtons(){const err=validatePattern(selectedFile),targets=selectedTransferIndexes(),send=$('#sendFile');if(send){send.disabled=targets.length===0||!!err||sending;send.textContent=targets.length?`An ausgewählte Maschinen senden (${targets.length})`:'Zielmaschine auswählen';}const previewButton=$('#openMotifPreview');if(previewButton)previewButton.disabled=!selectedFile||!!err||sending;$('#stopSend').disabled=!sending;updateGlobalStatus();}
async function sendSerialPattern(m,info,progressBase=0,progressShare=1,label='',threadPlan=null){
  const type=getFileType(info);let payload,modeLabel;
  if(threadPlan?.active&&type==='tap'){payload=buildHappyLinkTapPayload(info,threadPlan.sequence);modeLabel='HAPPYLINK HP1+TAP';log(`${m.name}: ${modeLabel} START: ${info.name} · Nadeln ${formatNeedleSequence(threadPlan.sequence)}`);log(`${m.name}: Aufbau ${HP1_SIZE} B HP1 + 24 Nullbytes + ${info.bytes.length} B TAP + 12 Nullbytes.`);}
  else{payload=info.bytes;if(type==='dst')payload=info.bytes.slice(DST_HEADER_SIZE);modeLabel=`LEGACY ${type.toUpperCase()}`;log(`${m.name}: ${modeLabel} START: ${info.name}`);}
  const total=payload.length;let sent=0;log(`${m.name}: Erste Nutzdaten: ${hex(payload.slice(0,64),64)}`);
  for(let offset=0;offset<total;offset+=LEGACY_BLOCK_SIZE){
    if(sendAbortRequested)throw new Error('Vom Benutzer abgebrochen');
    const chunk=payload.slice(offset,Math.min(offset+LEGACY_BLOCK_SIZE,total));
    const res=await fetch(`/api/serial/write?machine=${m.index}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:chunk});
    if(!res.ok){let msg=`HTTP ${res.status}`;try{const j=await res.json();if(j.error)msg=j.error;}catch{}m.connected=false;renderMachines();throw new Error(msg);}
    sent+=chunk.length;
    const machinePct=total?sent/total:1,overall=(progressBase+machinePct*progressShare)*100;
    setProgress(overall,`${m.name}${label}: ${sent} / ${total} Byte · ${overall.toFixed(0)} %`);
    log(`${m.name} TX Block ${Math.floor(offset/LEGACY_BLOCK_SIZE)+1}: ${chunk.length} B`);
    // Backend-AutoCOM: File.Write kann bereits zurückkehren, sobald Windows den Block
    // in den Treiberpuffer übernommen hat. Deshalb vor dem nächsten 512-B-Block
    // mindestens die physikalische Sendezeit bei 38400/8N1 plus Pause abwarten.
    const wireTimeMs=Math.ceil((chunk.length*10*1000)/38400);
    await new Promise(r=>setTimeout(r,wireTimeMs+18));
  }
  log(`${m.name}: ${modeLabel} ENDE – ${total} B übertragen.`);
}

async function sendPicoPattern(m,info,progressBase=0,progressShare=1,label=''){
  if(info.bytes.length>PICO_MAX_FILE)throw new Error(`Datei ist für den Floppy-Puffer zu groß (${fmtBytes(info.bytes.length)}; empfohlen max. ${fmtBytes(PICO_MAX_FILE)}).`);
  const url=normalizePicoUrl(appState.settings?.picoUrl);const c=new AbortController();const timer=setTimeout(()=>c.abort(),30000);
  log(`${m.name}: WLAN-Upload an Pico gestartet: ${info.name} (${info.bytes.length} B)`);setProgress(progressBase*100,`${m.name}${label}: Datei wird an Pico übertragen …`);
  try{
    const endpoint=`/api/pico/pattern?base=${encodeURIComponent(url)}&name=${encodeURIComponent(info.name)}`;
    const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:info.bytes,signal:c.signal});
    if(!res.ok){let msg='HTTP '+res.status;try{const j=await res.json();if(j.error)msg=j.error;}catch{}throw new Error(msg);}
    const data=await res.json();m.connected=true;m.lastSeen=Date.now();setProgress((progressBase+progressShare)*100,`${m.name}${label}: Pico bereit · jetzt am SFR rechten Knopf drücken`);log(`${m.name}: Pico bestätigt ${data.pattern_name||info.name}, ${data.pattern_size||info.bytes.length} B. Virtueller USB-Stick neu bereitgestellt; SFR muss die Datei noch in den internen Floppy-Puffer übernehmen.`);
  }finally{clearTimeout(timer);}
}
async function sendPatternToMachines(targetIndexes){
  const validationError=validatePattern(selectedFile);if(validationError){alert(validationError);log(`SENDEN abgebrochen: ${validationError}`);return;}if(sending)return;
  const targets=[...new Set(targetIndexes)].map(i=>machines[i]).filter(m=>m?.connected);if(!targets.length){alert('Keine der gewählten Maschinen ist verbunden.');return;}
  const threadPlans=await prepareThreadPlans(targets);if(threadPlans===null)return;
  sendAbortRequested=false;sending=true;updateButtons();let completed=0;const failures=[];
  try{
    for(let ti=0;ti<targets.length;ti++){
      if(sendAbortRequested)break;const m=targets[ti],base=ti/targets.length,share=1/targets.length,label=` (${ti+1}/${targets.length})`,plan=threadPlans.get(m.index)||null;
      try{if(m.kind==='pico'){await sendPicoPattern(m,selectedFile,base,share,label);const loaded=await hcaConfirm(`${m.name}: Die Datei ist jetzt auf dem virtuellen USB-Stick bereit.

1. Am SFR1M44-FU-DL den rechten Knopf drücken (USB → Floppy-Puffer).
2. Das Muster anschließend an der HCA vom Floppy-Laufwerk einlesen.

Wenn das erledigt ist, OK drücken. Dann wird die Datei im Maschinenbestand als auf ${m.name} geladen gespeichert.`);if(loaded)recordTransfer(m.index,selectedFile,[]);else log(`${m.name}: Datei am Pico bereit, aber noch nicht als auf der HCA geladen bestätigt.`);}else{await sendSerialPattern(m,selectedFile,base,share,label,plan);recordTransfer(m.index,selectedFile,plan?.sequence||null);}completed++;}
      catch(err){failures.push(`${m.name}: ${err.message||err}`);log(`${m.name}: SENDEN FEHLER: ${err.message||err}`);if(m.kind==='pico')m.connected=false;if(sendAbortRequested)break;}
      if(ti<targets.length-1&&!sendAbortRequested)await new Promise(r=>setTimeout(r,150));
    }
    if(sendAbortRequested)setProgress(100,`Übertragung abgebrochen. ${completed}/${targets.length} abgeschlossen.`);else if(failures.length)setProgress(100,`${completed}/${targets.length} abgeschlossen; ${failures.length} Fehler.`);else setProgress(100,`${completed}/${targets.length} Maschine(n) erfolgreich beschrieben.`);
  }finally{sending=false;sendAbortRequested=false;renderMachines();updateButtons();}
}
$('#sendFile').addEventListener('click',()=>sendPatternToMachines(selectedTransferIndexes()));$('#stopSend').addEventListener('click',()=>{sendAbortRequested=true;log('Abbruch angefordert …');});

function recordTransfer(machineIndex,info,needleSequenceOverride=null){
  const list=appState.inventory[machineIndex]||(appState.inventory[machineIndex]=[]),key=`${(info.name||'').toLowerCase()}|${info.size||0}`,existing=list.find(x=>x.key===key);
  const entry={key,name:info.name,size:info.size,type:(getFileType(info)||'').toUpperCase(),nasPath:info.nasPath||'',needleSequence:normalizeNeedleSequence(needleSequenceOverride||info.needleSequence),hp1Name:info.hp1Name||'',transferredAt:new Date().toISOString()};if(existing)Object.assign(existing,entry);else list.unshift(entry);saveStateSoon();renderInventory();renderProduction();
}
function renderInventory(){
  const host=$('#inventory');host.innerHTML='';machines.forEach((m,i)=>{const items=appState.inventory[i]||[],card=document.createElement('div');card.className='inventory-machine';const rows=items.length?items.map((it,idx)=>`<div class="inventory-row"><div><div class="inventory-name">${escapeHtml(it.name)}</div><div class="inventory-meta">${escapeHtml(it.type||'')} · ${fmtBytes(it.size||0)} · ${formatDateTime(it.transferredAt)}${it.nasPath?' · Synology Drive':''}${Array.isArray(it.needleSequence)&&it.needleSequence.length?` · Nadeln ${escapeHtml(formatNeedleSequence(it.needleSequence))}`:''}</div></div><button class="btn danger" data-inv-delete="${i}:${idx}">Gelöscht</button></div>`).join(''):'<div class="inventory-empty">Noch keine Datei eingetragen.</div>';card.innerHTML=`<div class="inventory-head"><div><strong>${escapeHtml(m.name)}</strong><div class="inventory-meta">${items.length} Datei${items.length===1?'':'en'} laut Manager · ${getMachineThreadIds(i).filter(Boolean).length}/${MAX_NEEDLE_NUMBER} Nadeln belegt</div></div><div class="actions-row"><button class="btn secondary" data-thread-setup="${i}">Nadelbelegung</button><button class="btn danger" data-inv-clear="${i}" ${items.length?'':'disabled'}>Alle gelöscht</button></div></div>${rows}`;host.appendChild(card);});
  host.querySelectorAll('[data-thread-setup]').forEach(b=>b.addEventListener('click',()=>openMachineThreads(Number(b.dataset.threadSetup))));
  host.querySelectorAll('[data-inv-delete]').forEach(b=>b.addEventListener('click',async()=>{const[mi,idx]=b.dataset.invDelete.split(':').map(Number),it=appState.inventory[mi]?.[idx];if(!it)return;if(!await hcaConfirm(`${it.name}\n\nNur aus der Bestandsliste entfernen?`))return;appState.inventory[mi].splice(idx,1);saveStateSoon();renderInventory();renderProduction();log(`${machines[mi].name}: ${it.name} als gelöscht markiert.`);}));
  host.querySelectorAll('[data-inv-clear]').forEach(b=>b.addEventListener('click',async()=>{const mi=Number(b.dataset.invClear);if(!appState.inventory[mi]?.length)return;if(!await hcaConfirm(`${machines[mi].name}: Wirklich alle Dateien als gelöscht markieren?`))return;appState.inventory[mi]=[];saveStateSoon();renderInventory();renderProduction();log(`${machines[mi].name}: Bestandsliste geleert.`);}));
}

function availablePatterns(){const map=new Map();appState.inventory.forEach((list,mi)=>list.forEach(it=>{const k=`${it.name.toLowerCase()}|${it.size||0}`;if(!map.has(k))map.set(k,{key:k,name:it.name,size:it.size,type:it.type,machines:[],needleSequence:normalizeNeedleSequence(it.needleSequence),hp1Name:it.hp1Name||''});const pattern=map.get(k);pattern.machines.push(mi);if(!pattern.needleSequence.length&&Array.isArray(it.needleSequence)&&it.needleSequence.length){pattern.needleSequence=normalizeNeedleSequence(it.needleSequence);pattern.hp1Name=it.hp1Name||pattern.hp1Name;}}));return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'de'));}
function totalTarget(p){return Object.values(p?.targets||{}).reduce((s,v)=>s+(Number(v)||0),0)}
function totalDone(p){return Object.keys(p?.targets||{}).reduce((s,k)=>s+Math.min(Number(p.done?.[k])||0,Number(p.targets?.[k])||0),0)}
function renderProduction(){
  const patterns=availablePatterns(),sel=$('#productionPattern');sel.innerHTML=patterns.length?patterns.map(p=>`<option value="${escapeHtml(p.key)}">${escapeHtml(p.name)} · ${p.machines.map(i=>machines[i].name).join(', ')}</option>`).join(''):'<option value="">Noch kein übertragenes Stickmotiv vorhanden</option>';$('#openNewProduction').disabled=!patterns.length;
  const running=appState.productions.filter(p=>p.status==='running'||p.status==='paused').sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));$('#productionBadge').textContent=running.length;$('#statProductions').textContent=running.length;
  const list=$('#productionList');list.innerHTML=running.length?running.map(p=>{const t=totalTarget(p),d=totalDone(p),pct=t?d/t*100:0;return `<div class="production-list-row"><div><strong>${escapeHtml(p.patternName)}</strong><small>${p.status==='paused'?'Unterbrochen':'Laufend'} · ${formatDateTime(p.updatedAt)}</small></div><div><div class="mini-progress"><div style="width:${pct}%"></div></div><small>${d} / ${t}</small></div><button class="btn primary" data-load-prod="${p.id}">Fortsetzen</button></div>`}).join(''):'<div class="inventory-empty">Keine laufende oder unterbrochene Produktion.</div>';
  list.querySelectorAll('[data-load-prod]').forEach(b=>b.addEventListener('click',()=>loadProduction(b.dataset.loadProd)));
  const completed=appState.productions.filter(p=>p.status==='completed').sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,8);$('#completedProductions').innerHTML=completed.length?completed.map(p=>`<div class="completed-row"><div><strong>${escapeHtml(p.patternName)}</strong><br><small>${totalDone(p)} Stück · abgeschlossen ${formatDateTime(p.updatedAt)}</small></div><button class="btn secondary" data-view-completed="${p.id}">Ansehen</button></div>`).join(''):'<div class="inventory-empty">Noch keine abgeschlossene Produktion.</div>';
  $('#completedProductions').querySelectorAll('[data-view-completed]').forEach(b=>b.addEventListener('click',()=>loadProduction(b.dataset.viewCompleted,true)));
  renderActiveProduction();updateGlobalStatus();
}
function renderActiveProduction(){
  const p=appState.productions.find(x=>x.id===currentProductionId);
  if(!p){$('#activeProduction').classList.add('hidden');$('#activeProductionEmpty').classList.remove('hidden');return;}
  $('#activeProductionEmpty').classList.add('hidden');$('#activeProduction').classList.remove('hidden');
  $('#prodTitle').textContent=p.patternName;
  $('#prodMeta').textContent=[p.status==='paused'?'Unterbrochen':p.status==='completed'?'Abgeschlossen':'Laufend',p.orderNo?`Auftrag ${p.orderNo}`:'',p.article||'',p.sku?`Art.-Nr. ${p.sku}`:'',`gestartet ${formatDateTime(p.createdAt)}`].filter(Boolean).join(' · ');const prodNeedles=$('#prodNeedles'),needleText=formatNeedleSequence(p.needleSequence);if(prodNeedles){prodNeedles.textContent=needleText?`Nadelfolge: ${needleText}`:'';prodNeedles.classList.toggle('hidden',!needleText);}
  const t=totalTarget(p),d=totalDone(p),remaining=Math.max(0,t-d),pct=t?d/t*100:0;
  $('#prodTotalText').textContent=`${d} / ${t}`;$('#prodTotalBar').style.width=`${pct}%`;$('#prodRemaining').textContent=remaining;
  const grid=$('#sizeGrid');grid.innerHTML='';
  SIZE_GROUPS.forEach(group=>{
    const planned=group.sizes.filter(size=>(Number(p.targets?.[sizeKey(group.id,size)])||0)>0);
    if(!planned.length)return;
    const section=document.createElement('section');section.className='size-group-section';
    const gd=planned.reduce((sum,size)=>sum+(Number(p.done?.[sizeKey(group.id,size)])||0),0);
    const gt=planned.reduce((sum,size)=>sum+(Number(p.targets?.[sizeKey(group.id,size)])||0),0);
    section.innerHTML=`<div class="size-group-head"><div><span class="eyebrow">TEXTILGRUPPE</span><h3>${escapeHtml(group.label)}</h3></div><strong>${gd} / ${gt}</strong></div><div class="size-cards"></div>`;
    const cards=section.querySelector('.size-cards');
    cards.style.gridTemplateColumns=`repeat(${Math.max(1,planned.length)}, minmax(0,1fr))`;
    planned.forEach(size=>{
      const key=sizeKey(group.id,size),target=Number(p.targets?.[key])||0,done=Number(p.done?.[key])||0,complete=done>=target;
      const card=document.createElement('div');card.className=`size-card ${complete?'complete':''}`;
      card.innerHTML=`<div class="size-name">${escapeHtml(size)}</div><div class="size-count">${done} <span>/ ${target}</span></div><div class="size-remaining">${Math.max(0,target-done)} offen</div><button type="button" class="size-main-btn" data-size-action="plus" data-size-key="${escapeHtml(key)}" ${complete||p.status==='completed'?'disabled':''}>${complete?'✓ Fertig':'+1 fertig'}</button><button type="button" class="undo-btn" data-size-action="minus" data-size-key="${escapeHtml(key)}" ${done===0||p.status==='completed'?'disabled':''}>−1 Korrektur</button><button type="button" class="undo-btn" data-size-label="${escapeHtml(key)}">Etikett</button>`;
      cards.appendChild(card);
    });
    grid.appendChild(section);
  });
  if(!grid.children.length)grid.innerHTML='<div class="inventory-empty">Für diese Produktion sind keine Größen eingeplant.</div>';
  $('#pauseProduction').disabled=p.status==='completed';$('#finishProduction').disabled=p.status==='completed';$('#pauseProduction').textContent=p.status==='paused'?'Produktion schließen':'Produktion unterbrechen';
}
async function changeDone(id,key,delta){
  const p=appState.productions.find(x=>x.id===id);if(!p||p.status==='completed')return;
  const target=Number(p.targets?.[key])||0;if(target<=0)return;if(!p.done)p.done={};
  const before=Number(p.done[key])||0,after=clamp(before+delta,0,target);if(after===before)return;
  p.done[key]=after;p.status='running';p.updatedAt=new Date().toISOString();
  const info=sizeInfoFromKey(key);log(`Produktion ${p.patternName}: ${info.group?.label||''} ${info.size} → ${after} / ${target} fertig.`);
  renderProduction();saveStateSoon();
  if(delta>0){
    await printProductLabel({order_no:p.orderNo||'',sku:p.sku||'',article:p.article||p.patternName||'',size:info.size,color:p.color||''},false);
  }
}
async function printLocalProductionLabel(id,key){
  const p=appState.productions.find(x=>x.id===id);if(!p)return;const info=sizeInfoFromKey(key);
  await printProductLabel({order_no:p.orderNo||'',sku:p.sku||'',article:p.article||p.patternName||'',size:info.size,color:p.color||''},true);
}
function loadProduction(id,readOnly=false){const p=appState.productions.find(x=>x.id===id);if(!p)return;currentProductionId=id;if(!readOnly&&p.status!=='completed'){p.status='running';p.updatedAt=new Date().toISOString();saveStateSoon();}$('#runningProductionList').classList.add('hidden');renderProduction();showView('production');if(!readOnly&&p.status!=='completed')requestProductionFullscreen();else setProductionMonitorMode(false);}

