    section.innerHTML=`<div class="quantity-group-head"><div><span class="eyebrow">TEXTILGRUPPE</span><h3>${escapeHtml(group.label)}</h3></div><span><strong data-group-total="${group.id}">0</strong> Stück</span></div><div class="quantity-items"></div>`;
