async function saveSettings(){
  const root=$('#settingNasRoot').value.trim(),names=$$('.machine-name-input').map((i,idx)=>i.value.trim()||`HCA ${idx+1}`),picoUrl=normalizePicoUrl($('#settingPicoUrl').value);
  const serialPorts=[0,1,2].map(i=>String($(`#serialPort${i}`)?.value||'').trim().toUpperCase());
  const used=serialPorts.filter(Boolean);if(new Set(used).size!==used.length){alert('Jeder COM-Port darf nur einer Maschine zugeordnet werden.');return;}
  for(const port of used){if(!/^COM\d+$/i.test(port)){alert(`Ungültiger COM-Port: ${port}\n\nBitte z. B. COM4 eintragen.`);return;}}
  try{
    const res=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({synology_root:root,machine_names:names.slice(0,3),serial_ports:serialPorts})});
    const data=await res.json();if(!res.ok)throw new Error(data.error||'Speichern fehlgeschlagen');
    statusData.nasRoot=root;statusData.serialPorts=serialPorts;names.forEach((n,i)=>machines[i].name=n);
    appState.settings=appState.settings||{};appState.settings.machine4Name=names[3]||'HCA 4';appState.settings.picoUrl=picoUrl;await saveState();
    $('#settingPicoUrl').value=picoUrl;alert('Einstellungen gespeichert. Die COM-Ports werden automatisch verbunden.');
    await refreshSerialStatus();renderMachines();renderInventory();renderBranding();renderAppIcon();await loadNas('');await checkPicoConnection(false);
  }catch(err){alert(`Einstellungen konnten nicht gespeichert werden: ${err.message||err}`);}
}
