let latestGithubUpdate=null;
function githubUpdateChannel(){return appState.settings?.updateChannel==='beta'?'beta':'stable';}
function showManualUpdateRestart(version,statusElement){
  const label=String(version||'').trim();
  const updateName=label?`Update ${label}`:'Das Update';
  if(statusElement)statusElement.textContent=`${updateName} wurde eingespielt. Bitte HCA schließen und erneut öffnen.`;
  alert(`${updateName} wurde erfolgreich eingespielt.\n\nBitte den HCA Produktionsmanager jetzt selbst schließen und anschließend erneut öffnen.`);
}
function setGithubUpdateUI(data,manual=false){
  const st=$('#githubUpdateStatus'),notes=$('#githubReleaseNotes'),btn=$('#installGithubUpdate'),banner=$('#githubUpdateBanner');
  latestGithubUpdate=data?.available?data:null;
  const cur=String(data?.current_version||'').trim();
  if(cur){const ver=$('#appVersion');if(ver)ver.textContent=`v${cur}`;}
  if(data?.available){
    const latest=String(data.latest_version||data.tag||'').replace(/^v/i,'');
    st.textContent=`Update ${latest} verfügbar · ${data.asset_name||'.hcaupdate'}${data.sha256_present?' · SHA256 vorhanden':' · SHA256 fehlt'}`;
    btn?.classList.remove('hidden');
    if(notes){notes.textContent=String(data.notes||'Keine Release Notes hinterlegt.');notes.classList.remove('hidden');}
    if(banner){banner.classList.remove('hidden');$('#githubUpdateBannerTitle').textContent=`Update ${latest} verfügbar`;$('#githubUpdateBannerText').textContent=String(data.release_name||data.notes||'Neue Version des HCA Produktionsmanagers verfügbar.').split('\n')[0].slice(0,180);}
  }else{
    btn?.classList.add('hidden');if(notes){notes.textContent='';notes.classList.add('hidden');}
    banner?.classList.add('hidden');
    if(data?.message)st.textContent=`Version ${cur||'–'} · ${data.message}`;
    else if(data?.latest_version)st.textContent=`Version ${cur||'–'} ist aktuell. Neueste ${githubUpdateChannel()}-Version: ${data.latest_version}.`;
    else st.textContent=`Version ${cur||'–'} · Kein neueres Update verfügbar.`;
    if(manual&&data?.ok)alert('Der HCA Produktionsmanager ist auf dem gewählten Updatekanal aktuell.');
  }
}
async function checkGithubUpdate(manual=false){
  const st=$('#githubUpdateStatus'),btn=$('#checkGithubUpdate');if(btn)btn.disabled=true;if(st)st.textContent='GitHub wird nach Updates geprüft …';
  try{
    const res=await fetch(`/api/update/github/check?channel=${encodeURIComponent(githubUpdateChannel())}`,{cache:'no-store'});
    const data=await res.json();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);
    setGithubUpdateUI(data,manual);return data;
  }catch(err){if(st)st.textContent=`Updatesuche nicht möglich: ${err.message||err}`;if(manual)alert(`GitHub-Updates konnten nicht geprüft werden:\n${err.message||err}`);return null;}
  finally{if(btn)btn.disabled=false;}
}
async function installGithubUpdate(){
  const data=latestGithubUpdate;if(!data)return;
  const version=String(data.latest_version||data.tag||'').replace(/^v/i,'');
  if(!data.sha256_present){alert('Dieses GitHub Release enthält keine SHA256-Prüfsumme und wird deshalb nicht automatisch installiert.');return;}
  if(!await hcaConfirm(`HCA Produktionsmanager ${version} installieren?\n\nDas Update wird direkt von GitHub geladen, per SHA256 geprüft und anschließend installiert.\n\nDanach schließt und öffnest du den Produktionsmanager selbst.`))return;
  const buttons=[$('#installGithubUpdate'),$('#githubUpdateInstallTop')].filter(Boolean);buttons.forEach(b=>b.disabled=true);
  const st=$('#githubUpdateStatus');if(st)st.textContent=`Update ${version} wird von GitHub geladen und geprüft …`;
  try{
    const res=await fetch(`/api/update/github/install?channel=${encodeURIComponent(githubUpdateChannel())}`,{method:'POST'});
    const result=await res.json();if(!res.ok)throw new Error(result.error||`HTTP ${res.status}`);
    showManualUpdateRestart(result.version||version,st);
  }catch(err){
    const message=String(err?.message||err||'');
    if(/failed to fetch|networkerror|network error|load failed/i.test(message)){
      showManualUpdateRestart(version,st);
      return;
    }
    buttons.forEach(b=>b.disabled=false);if(st)st.textContent=`GitHub-Update fehlgeschlagen: ${message}`;alert(`Update konnte nicht installiert werden:\n${message}`);
  }
}
