    // bis der Anwender es nach der Abschlussmeldung manuell schließt.
    const message=String(err?.message||err||'');
    if(/failed to fetch|networkerror|network error|load failed/i.test(message)){
      showManualUpdateRestart('',st);
      return;
    }
    st.textContent=`Update fehlgeschlagen: ${message}`;btn.disabled=false;alert(`Update konnte nicht eingespielt werden:\n${message}`);
