function picoSleep(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
function picoBytesToBase64(bytes){let out='';const step=0x4000;for(let i=0;i<bytes.length;i+=step)out+=String.fromCharCode(...bytes.subarray(i,Math.min(bytes.length,i+step)));return btoa(out);}
async function picoReadUntil(reader,marker,timeoutMs=5000){
  const dec=new TextDecoder();let text='';const deadline=Date.now()+timeoutMs;let pending=reader.read();
  while(Date.now()<deadline){
    const remaining=deadline-Date.now();
    const result=await Promise.race([pending,new Promise(resolve=>setTimeout(()=>resolve({timeout:true}),Math.min(300,remaining)))]);
    if(result?.timeout)continue;
    if(result.done)break;
    if(result.value){text+=dec.decode(result.value,{stream:true});if(text.includes(marker))return text;}
    pending=reader.read();
  }
  throw new Error(`Zeitüberschreitung bei Pico-Antwort (${marker==='raw REPL'?'Raw-REPL':'Befehl'}).${text?` Antwort: ${text.slice(-300)}`:''}`);
}
async function picoEnterRawRepl(reader,writer){
  // Ctrl-C first leaves MicroPython at the normal " >>> " prompt. Do not mistake that prompt
  // for Raw-REPL. Ctrl-A then switches to Raw-REPL; wait for its explicit banner.
  await writer.write(Uint8Array.of(3,3));
  await picoSleep(180);
  await writer.write(Uint8Array.of(1));
  let text=await picoReadUntil(reader,'raw REPL',5000);
  if(!/raw REPL/i.test(text))throw new Error('MicroPython Raw-REPL wurde nicht erreicht.');
  if(!/>\s*$/.test(text))text+=await picoReadUntil(reader,'>',2000);
  if(!/>\s*$/.test(text))throw new Error('MicroPython Raw-REPL-Prompt wurde nicht erreicht.');
}
async function picoRawExec(reader,writer,code,timeoutMs=8000){
  const enc=new TextEncoder();await writer.write(enc.encode(code));await writer.write(Uint8Array.of(4));const text=await picoReadUntil(reader,'\x04>',timeoutMs);
  const ok=text.indexOf('OK');if(ok<0)throw new Error(`MicroPython hat den Befehl nicht bestätigt: ${text.slice(-400)}`);
  const payload=text.slice(ok+2);const parts=payload.split('\x04');const stdout=parts[0]||'',stderr=parts[1]||'';if(stderr.trim())throw new Error(stderr.trim());return stdout;
}
async function picoUploadFile(reader,writer,name,text){
  await picoRawExec(reader,writer,`f=open(${JSON.stringify(name)},'wb');f.close()`);
  const bytes=new TextEncoder().encode(text);for(let off=0;off<bytes.length;off+=480){const b64=picoBytesToBase64(bytes.subarray(off,Math.min(bytes.length,off+480)));await picoRawExec(reader,writer,`import ubinascii;f=open(${JSON.stringify(name)},'ab');f.write(ubinascii.a2b_base64('${b64}'));f.close()`);}
}
