$('#configurePicoUsb').addEventListener('click',async()=>{
  const ssid=$('#picoWifiSsid').value.trim(),password=$('#picoWifiPassword').value;if(!ssid){alert('Bitte WLAN-Name (SSID) eingeben.');return;}if(!('serial'in navigator)){alert('Web Serial ist nicht verfügbar. Bitte Edge oder Chrome verwenden.');return;}
  const btn=$('#configurePicoUsb'),st=$('#picoInstallStatus');let port=null,reader=null,writer=null;
  try{
    btn.disabled=true;st.textContent='Bridge wird installiert …';
    const [diskRes,bridgeRes,bootRes,mainRes]=await Promise.all([fetch('/pico/hca_disk.py',{cache:'no-store'}),fetch('/pico/hca_bridge.py',{cache:'no-store'}),fetch('/pico/boot.py',{cache:'no-store'}),fetch('/pico/main.py',{cache:'no-store'})]);
    if(!diskRes.ok||!bridgeRes.ok||!bootRes.ok||!mainRes.ok)throw new Error('Pico-Bridge-Dateien fehlen im HCA-Manager-Paket.');
    const diskText=await diskRes.text(),bridgeText=await bridgeRes.text(),bootText=await bootRes.text(),mainText=await mainRes.text();
    port=await navigator.serial.requestPort();await port.open({baudRate:115200,dataBits:8,stopBits:1,parity:'none',flowControl:'none'});reader=port.readable.getReader();writer=port.writable.getWriter();
    await picoEnterRawRepl(reader,writer);
    await picoUploadFile(reader,writer,'hca_disk.py',diskText);await picoUploadFile(reader,writer,'hca_bridge.py',bridgeText);await picoUploadFile(reader,writer,'boot.py',bootText);await picoUploadFile(reader,writer,'main.py',mainText);
    const cfg=JSON.stringify({ssid,password});await picoUploadFile(reader,writer,'hca_config.json',cfg);
    st.textContent='WLAN wird geprüft …';
    const probe=`import network,time\ntry:\n network.hostname('hca-pico')\nexcept: pass\nw=network.WLAN(network.STA_IF);w.active(True);w.connect(${JSON.stringify(ssid)},${JSON.stringify(password)})\nfor _ in range(120):\n if w.isconnected(): break\n time.sleep_ms(100)\nprint('HCA_IP='+ (w.ifconfig()[0] if w.isconnected() else ''))`;
    const out=await picoRawExec(reader,writer,probe,18000);const m=out.match(/HCA_IP=([^\r\n]*)/);const ip=(m?.[1]||'').trim();if(!ip)throw new Error('WLAN-Daten wurden gespeichert, aber der Pico konnte sich nicht mit dem WLAN verbinden. SSID/Passwort prüfen.');
    appState.settings=appState.settings||{};appState.settings.picoUrl=`http://${ip}`;$('#settingPicoUrl').value=appState.settings.picoUrl;await saveState();
    $('#picoWifiPassword').value='';st.textContent=`Bridge installiert · ${ip}`;log(`Pico-Floppy-Bridge installiert. WLAN-IP: ${ip}`);
    // Reset command deliberately drops the serial connection because the Pico re-enumerates as USB mass storage.
    try{await writer.write(new TextEncoder().encode('import machine;machine.reset()'));await writer.write(Uint8Array.of(4));}catch{}
    alert(`Pico ist eingerichtet.\n\nWLAN-IP: ${ip}\n\nNach dem Neustart meldet er sich als USB-Floppy-Massenspeicher. Den Pico jetzt vom PC trennen und an den SFR1M44-FU-DL anschließen. Anschließend im HCA Manager „Pico-Verbindung testen“ verwenden.`);
  }catch(err){st.textContent='Einrichtung fehlgeschlagen';alert(`Pico-USB-Einrichtung fehlgeschlagen: ${err.message||err}`);}finally{try{reader?.releaseLock();}catch{}try{writer?.releaseLock();}catch{}try{await port?.close();}catch{}btn.disabled=false;}
});
async function picoReadForDiagnosis(reader,ms,onText){
  const dec=new TextDecoder();const deadline=Date.now()+ms;let pending=reader.read();
  while(Date.now()<deadline){
    const remaining=deadline-Date.now();
    const result=await Promise.race([
      pending,
      new Promise(resolve=>setTimeout(()=>resolve({timeout:true}),Math.min(300,remaining)))
    ]);
    if(result?.timeout)continue;
    if(result.done)break;
    if(result.value){
      const t=dec.decode(result.value,{stream:true});
      if(t)onText(t);
    }
    pending=reader.read();
  }
}
$('#diagnosePicoUsb').addEventListener('click',async()=>{
  if(!('serial'in navigator)){alert('Web Serial ist nicht verfügbar. Bitte Edge oder Chrome verwenden.');return;}
  const btn=$('#diagnosePicoUsb'),out=$('#picoDiagnosticOutput');let port=null,reader=null,writer=null;
  out.value='';btn.disabled=true;
  const add=t=>{out.value+=t;out.scrollTop=out.scrollHeight;};
  try{
    add('Pico-Diagnose startet …\r\nBitte den COM-Port des Pico auswählen.\r\n\r\n');
    port=await navigator.serial.requestPort();
    await port.open({baudRate:115200,dataBits:8,stopBits:1,parity:'none',flowControl:'none'});
    reader=port.readable.getReader();writer=port.writable.getWriter();

    // Stop the current program and return to the normal MicroPython REPL.
    await writer.write(Uint8Array.of(3,3));
    await picoSleep(250);
    await writer.write(Uint8Array.of(2));
    await picoSleep(250);

    add('--- Soft-Neustart ---\r\n');
    // Ctrl-D performs a MicroPython soft reset while keeping the same serial
    // connection, so boot.py/main.py output can be captured reliably.
    await writer.write(Uint8Array.of(4));
    await picoReadForDiagnosis(reader,20000,add);

    add('\r\n--- Diagnose beendet ---\r\n');
    const txt=out.value;
    if(/HCA_PICO_IP=/.test(txt))add('ERGEBNIS: WLAN/Bridge-Start wurde erreicht.\r\n');
    if(/HCA_USB_MSC_ERROR/.test(txt))add('ERGEBNIS: Fehler beim Start des USB-Massenspeichers erkannt.\r\n');
    if(/Traceback|HCA_BOOT_PREP_ERROR/.test(txt))add('ERGEBNIS: Python-Bootfehler erkannt. Bitte diese Ausgabe senden.\r\n');
    if(!/HCA_PICO_IP=|HCA_USB_MSC_ERROR|Traceback|HCA_BOOT_PREP_ERROR/.test(txt))add('ERGEBNIS: Kein HCA-Startsignal erkannt. Bitte diese Ausgabe senden.\r\n');
  }catch(err){
    add(`\r\nFEHLER: ${err.message||err}\r\n`);
  }finally{
    try{await reader?.cancel();}catch{}
    try{reader?.releaseLock();}catch{}
    try{writer?.releaseLock();}catch{}
    try{await port?.close();}catch{}
    btn.disabled=false;
  }
});
