function ensureHcaWindowPresence(){try{window.focus();const left=Number.isFinite(screen.availLeft)?screen.availLeft:0,top=Number.isFinite(screen.availTop)?screen.availTop:0,w=screen.availWidth||screen.width,h=screen.availHeight||screen.height;if(typeof window.moveTo==='function')window.moveTo(left,top);if(typeof window.resizeTo==='function')window.resizeTo(w,h);window.focus()}catch{}}
window.addEventListener('pageshow',()=>{setTimeout(ensureHcaWindowPresence,80);setTimeout(()=>window.focus(),500)});

