  if($('#settingBinLabelPrinter'))$('#settingBinLabelPrinter').value=String(appState.settings?.binLabelPrinter||appState.settings?.inventoryLabelPrinter||appState.settings?.productLabelPrinter||'');
  if($('#settingBinLabelWidth'))$('#settingBinLabelWidth').value=String(Number(appState.settings?.binLabelWidth)||75);
  if($('#settingBinLabelHeight'))$('#settingBinLabelHeight').value=String(Number(appState.settings?.binLabelHeight)||50);
  if($('#settingBinLabelRotation'))$('#settingBinLabelRotation').value=String([0,90,180,270].includes(Number(appState.settings?.binLabelRotation))?Number(appState.settings.binLabelRotation):0);
  $('#settingShippingLabelPrinter').value=String(appState.settings?.shippingLabelPrinter||'');
  $('#settingShippingLabelWidth').value=String(Number(appState.settings?.shippingLabelWidth)||105);
  $('#settingShippingLabelHeight').value=String(Number(appState.settings?.shippingLabelHeight)||148);
  $('#settingLabelCompany').value=String(appState.settings?.labelCompany||'');
  $('#settingLabelAddress').value=String(appState.settings?.labelAddress||'');
  $('#settingLabelCity').value=String(appState.settings?.labelCity||'');
  $('#settingLabelCountry').value=String(appState.settings?.labelCountry||'Deutschland');
  $('#settingLabelContact').value=String(appState.settings?.labelContact||'');
  renderCareSettingsEditor();
  if($('#githubUpdateChannel'))$('#githubUpdateChannel').value=githubUpdateChannel();
  if($('#githubAutoUpdateCheck'))$('#githubAutoUpdateCheck').checked=appState.settings?.autoUpdateCheck!==false;
  log('HCA 1–3: feste COM-Port-Zuordnung wird vom Produktionsmanager automatisch verwaltet.');
  if(!('serial'in navigator))log('Hinweis: Web Serial ist nicht verfügbar; nur Pico-USB-Einrichtung und Pico-Diagnose benötigen Edge/Chrome Web Serial.');
  try{const res=await fetch('/api/status',{cache:'no-store'}),data=await res.json();statusData=data;if(data.version){const ver=$('#appVersion');if(ver)ver.textContent=`v${data.version}`;}if(Array.isArray(data.machineNames))data.machineNames.slice(0,3).forEach((n,i)=>machines[i].name=n||machines[i].name);machines[3].name=appState.settings?.machine4Name||machines[3].name;renderMachines();$('#settingNasRoot').value=data.nasRoot||'';$('#settingPicoUrl').value=normalizePicoUrl(appState.settings?.picoUrl);$$('.machine-name-input').forEach((el,i)=>el.value=machines[i].name);(Array.isArray(data.serialPorts)?data.serialPorts:[]).slice(0,3).forEach((port,i)=>{const el=$(`#serialPort${i}`);if(el)el.value=port||'';});if(data.nasConfigured&&data.nasReachable){$('#nasStatus').textContent=`Synology Drive lokal erreichbar: ${data.nasRoot}`;await loadNas('');}else if(data.nasConfigured){$('#nasStatus').textContent=`Ordner aktuell nicht erreichbar: ${data.nasRoot}`;$('#nasList').innerHTML='<div class="entry"><span>!</span><span class="name">Synology Drive / Windows-Pfad prüfen.</span></div>';}else{$('#nasStatus').textContent='Noch kein Stickdatei-Ordner konfiguriert.';}}catch(err){log(`Serverstatus konnte nicht geladen werden: ${err.message||err}`);}
