// HCA v0.10.3 · Shoppreise, schnelle Suche, Direktauftrag, Angebotsmail
// ===========================================================================
const HCA103={orderLines:[],orderSearchTimers:{},invoiceSearchTimers:{}};
function hca103Qty(line){const s=line?.config?.sizes||{};const n=Object.values(s).reduce((a,v)=>a+(Number(v)||0),0);return n>0?n:Math.max(1,Number(line?.quantity)||1)}
function hca103EnrichStep(line,step){const areas=Array.isArray(line?.config?.shop_areas)?line.config.shop_areas:[];let area=areas.find(a=>String(a?.name||'').toLowerCase().includes(String(step.position||'').toLowerCase())&&String(step.position||'').trim())||areas[0];if(area){step.area_id=step.area_id||area.id||'';step.area_name=step.area_name||area.name||'';step.area_index=Number.isFinite(step.area_index)?step.area_index:Math.max(0,areas.indexOf(area));const ass=Array.isArray(area.assignments)?area.assignments:[];if(ass.length===1){step.druckart_id=step.druckart_id||ass[0].druckart_id||'';step.cost_id=step.cost_id||ass[0].cost_id||'';step.bearbeitung_cost_id=step.bearbeitung_cost_id||ass[0].bearbeitung_cost_id||''}}}
async function hca103ShopPrice(line){if(!line?.product_id)return null;const qty=hca103Qty(line);(line.config?.production_steps||[]).forEach(s=>hca103EnrichStep(line,s));const res=await businessApi('/business/shop-price',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:line.product_id,quantity:qty,config:line.config})});line.unit_price=Number(res.base_unit)||0;const ps=line.config?.production_steps||[];(res.positions||[]).forEach((p,i)=>{if(!ps[i])return;ps[i].unit_price=(Number(p.print_per_item)||0)+(Number(p.bearbeitung_unit)||0);ps[i].setup_price=Number(p.setup_total)||0});line.config.shop_price_source=res.source||'woocommerce';line.config.shop_price_updated_at=new Date().toISOString();return res}
async function hca103RepriceQuote(){if(!activeBusinessQuote)return;const btn=$('#businessQuoteReprice');if(btn){btn.disabled=true;btn.textContent='Shoppreise werden geladen …'}try{for(const line of activeBusinessQuote.items||[])if(line.product_id)await hca103ShopPrice(line);renderBusinessQuoteEditor()}catch(e){alert('Shoppreise konnten nicht vollständig geladen werden:\n'+(e.message||e))}finally{if(btn){btn.disabled=false;btn.textContent='Shoppreise aktualisieren'}}}

// Angebot: Mail + Shoppreis-Schaltfläche ergänzen.
const hca103RenderQuote=renderBusinessQuoteEditor;
renderBusinessQuoteEditor=function(){hca103RenderQuote();const actions=$('#businessQuoteTopActions');if(actions&&activeBusinessQuote){if(!$('#businessQuoteReprice')&&!['accepted','rejected','expired'].includes(activeBusinessQuote.status)){const b=document.createElement('button');b.id='businessQuoteReprice';b.className='btn secondary';b.type='button';b.textContent='Shoppreise aktualisieren';b.onclick=hca103RepriceQuote;actions.prepend(b)}if(activeBusinessQuote.id&&!$('#businessQuoteEmail')){const b=document.createElement('button');b.id='businessQuoteEmail';b.className='btn secondary';b.type='button';b.textContent='✉ Angebot senden';b.onclick=hca103OpenQuoteMail;actions.prepend(b)}}}
const hca103SearchQuote=searchBusinessQuoteProducts;
searchBusinessQuoteProducts=async function(i,query){await hca103SearchQuote(i,query);const box=$(`[data-bq-results="${i}"]`);if(!box)return;box.querySelectorAll('[data-bq-product]').forEach(b=>{const old=b.onclick;b.onclick=async()=>{old?.();const line=activeBusinessQuote?.items?.[i],x=box._items?.[Number(String(b.dataset.bqProduct).split(':')[1])];if(line&&x){line.config.shop_areas=Array.isArray(x.areas)?x.areas:[];line.unit_price=Number(x.price)||line.unit_price||0;try{await hca103ShopPrice(line)}catch{}renderBusinessQuoteEditor()}}})}
async function hca103OpenQuoteMail(){if(!activeBusinessQuote?.id)return;let to='';try{const d=await ensureBusinessCustomerDetail(activeBusinessQuote.customer_id),c=(d?.contacts||[]).find(x=>x.id===activeBusinessQuote.contact_id)||(d?.contacts||[]).find(x=>x.is_primary);to=c?.email||d?.email||''}catch{}$('#businessQuoteEmailTo').value=to;$('#businessQuoteEmailSubject').value=`Angebot ${activeBusinessQuote.quote_no||''} · ${activeBusinessQuote.subject||''}`.trim();$('#businessQuoteEmailBody').value=`Guten Tag,\n\nvielen Dank für Ihre Anfrage. Anbei erhalten Sie unser Angebot ${activeBusinessQuote.quote_no||''}.\n\nBei Fragen stehen wir Ihnen gerne zur Verfügung.\n\nFreundliche Grüße\nWerbestudio Königswinter`;$('#businessQuoteEmailDialog').showModal()}
async function hca103SendQuoteMail(){const b=$('#sendBusinessQuoteEmail');b.disabled=true;try{await businessApi(`/sales/quotes/${encodeURIComponent(activeBusinessQuote.id)}/email`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to:$('#businessQuoteEmailTo').value.trim(),subject:$('#businessQuoteEmailSubject').value.trim(),message:$('#businessQuoteEmailBody').value})});$('#businessQuoteEmailDialog').close();alert('Angebot wurde per E-Mail gesendet.');await openBusinessQuoteEditor(activeBusinessQuote.id)}catch(e){alert('E-Mail konnte nicht gesendet werden:\n'+(e.message||e))}finally{b.disabled=false}}
$('#sendBusinessQuoteEmail')?.addEventListener('click',hca103SendQuoteMail);

// SMTP Einstellungen
async function hca103LoadMail(){try{const d=await businessApi('/mail/settings');const s=d.settings||{};$('#settingMailHost').value=s.host||'';$('#settingMailPort').value=s.port||587;$('#settingMailEncryption').value=s.security||'starttls';$('#settingMailUsername').value=s.username||'';$('#settingMailFromEmail').value=s.from_email||'';$('#settingMailFromName').value=s.from_name||'Werbestudio Königswinter';$('#settingMailPassword').value='';$('#settingMailPassword').placeholder=d.password_set?'gespeichert · leer = unverändert':'Passwort';$('#mailSettingsStatus').textContent=s.host?'Gespeichert':'Noch nicht eingerichtet'}catch(e){$('#mailSettingsStatus').textContent='Nicht verfügbar'}}
async function hca103SaveMail(){try{await businessApi('/mail/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({host:$('#settingMailHost').value.trim(),port:Number($('#settingMailPort').value)||587,security:$('#settingMailEncryption').value,username:$('#settingMailUsername').value.trim(),password:$('#settingMailPassword').value,from_email:$('#settingMailFromEmail').value.trim(),from_name:$('#settingMailFromName').value.trim()})});$('#settingMailPassword').value='';$('#mailSettingsStatus').textContent='Gespeichert'}catch(e){alert(e.message||e)}}
async function hca103TestMail(){try{$(`#mailSettingsStatus`).textContent='Test läuft …';await hca103SaveMail();const d=await businessApi('/mail/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to:$('#settingMailFromEmail').value.trim()})});$('#mailSettingsStatus').textContent='Testmail gesendet'}catch(e){$('#mailSettingsStatus').textContent='Fehler';alert(e.message||e)}}
$('#saveMailSettings')?.addEventListener('click',hca103SaveMail);$('#testMailSettings')?.addEventListener('click',hca103TestMail);

// Maschinenstatus nur in Produktion & Lager zeigen. Start zeigt Serverstatus.
function hca103StatusVisibility(){const cat=activeHcaCategory;const show=cat==='production'||cat==='inventory';$('#machineSidebarStatus')?.classList.toggle('hidden',!show);$$('.connection-indicator[data-connection-machine]').forEach(x=>x.classList.toggle('hidden',!show))}
const hca103ShowView=showView;showView=function(name,categoryOverride='',inventoryTarget=''){hca103ShowView(name,categoryOverride,inventoryTarget);hca103StatusVisibility();if(name==='dashboard')hca103CheckServer()}
async function hca103CheckServer(){const dot=$('#dashboardServerDot'),txt=$('#dashboardServerText');if(!txt)return;try{const r=await productionFetch('/api/health',{timeoutMs:4000});if(!r.ok)throw new Error();txt.textContent='Produktionsserver verbunden';dot?.classList.add('online')}catch{txt.textContent='Produktionsserver nicht erreichbar';dot?.classList.remove('online')}}

// Direktauftrag: gleiche Grundlogik wie Angebot.
function hca103NewOrderLine(v={}){return newBusinessQuoteLine(v)}
function hca103OrderLineHtml(l,i){const refined=(l.config?.production_steps||[]).length>0;return `<div class="business-quote-line"><div class="business-quote-line-head"><b>Position ${i+1}</b><div class="actions-row"><button class="btn secondary compact" type="button" data-o-ref="${i}">${refined?'Veredelung entfernen':'+ Veredelung'}</button><button class="btn secondary compact" type="button" data-o-del="${i}">×</button></div></div><div class="business-form-grid"><div class="span-2 business-product-search-wrap"><label>Artikel suchen</label><input class="text-input" data-o-search="${i}" placeholder="z. B. ID001, Polo, Kugelschreiber"><div class="business-product-results hidden" data-o-results="${i}"></div></div><div class="span-2"><label>Bezeichnung</label><input class="text-input" data-o-field="description" data-i="${i}" value="${escapeHtml(l.description||'')}"></div><div><label>SKU</label><input class="text-input" data-o-field="sku" data-i="${i}" value="${escapeHtml(l.sku||'')}"></div><div><label>Menge</label><input class="text-input" type="number" min="1" data-o-field="quantity" data-i="${i}" value="${hca103Qty(l)}"></div><div><label>Artikelpreis netto</label><input class="text-input" type="number" step=".01" data-o-field="unit_price" data-i="${i}" value="${Number(l.unit_price)||0}"></div><div><label>MwSt. %</label><input class="text-input" type="number" data-o-field="tax_rate" data-i="${i}" value="${Number(l.tax_rate)||19}"></div></div>${refined?`<div class="business-refinement-box"><h4>Veredelung</h4>${(l.config.production_steps||[]).map((s,si)=>`<div class="business-step-row"><select class="text-input" data-o-step="technique" data-oi="${i}" data-si="${si}">${Object.entries(BUSINESS_TECHNIQUES).map(([k,v])=>`<option value="${k}" ${s.technique===k?'selected':''}>${escapeHtml(v)}</option>`).join('')}</select><input class="text-input" data-o-step="position" data-oi="${i}" data-si="${si}" placeholder="Position" value="${escapeHtml(s.position||'')}"><input class="text-input" data-o-step="motif" data-oi="${i}" data-si="${si}" placeholder="Motiv" value="${escapeHtml(s.motif||'')}"><input class="text-input" type="number" min="1" data-o-step="colors_count" data-oi="${i}" data-si="${si}" value="${Number(s.colors_count)||1}"></div>`).join('')}</div>`:''}</div>`}
function hca103RenderOrderLines(){const h=$('#businessOrderLines');if(!h)return;h.innerHTML=HCA103.orderLines.map(hca103OrderLineHtml).join('');h.querySelectorAll('[data-o-field]').forEach(e=>e.oninput=()=>{const l=HCA103.orderLines[+e.dataset.i],k=e.dataset.oField;l[k]=['quantity','unit_price','tax_rate'].includes(k)?Number(e.value)||0:e.value});h.querySelectorAll('[data-o-ref]').forEach(b=>b.onclick=()=>{const l=HCA103.orderLines[+b.dataset.oRef];l.config.production_steps=(l.config.production_steps||[]).length?[]:[{technique:'stick',position:'',motif:'',colors_count:1,unit_price:0,setup_price:0}];hca103RenderOrderLines()});h.querySelectorAll('[data-o-del]').forEach(b=>b.onclick=()=>{HCA103.orderLines.splice(+b.dataset.oDel,1);if(!HCA103.orderLines.length)HCA103.orderLines=[hca103NewOrderLine()];hca103RenderOrderLines()});h.querySelectorAll('[data-o-step]').forEach(e=>e.oninput=()=>{HCA103.orderLines[+e.dataset.oi].config.production_steps[+e.dataset.si][e.dataset.oStep]=e.dataset.oStep==='colors_count'?Number(e.value)||1:e.value});h.querySelectorAll('[data-o-search]').forEach(e=>e.oninput=()=>{clearTimeout(HCA103.orderSearchTimers[e.dataset.oSearch]);HCA103.orderSearchTimers[e.dataset.oSearch]=setTimeout(()=>hca103OrderSearch(+e.dataset.oSearch,e.value),120)})}
async function hca103OrderSearch(i,q){const box=$(`[data-o-results="${i}"]`);if(!box||String(q).trim().length<2){box?.classList.add('hidden');return}box.classList.remove('hidden');box.innerHTML='<div class="business-loading compact">Artikelcache wird durchsucht …</div>';try{const d=await businessApi(`/woocommerce/products/search?q=${encodeURIComponent(q)}&limit=12`);box.innerHTML=(d.items||[]).map((x,n)=>`<button type="button" data-op="${n}"><b>${escapeHtml(x.name)}</b><span>${escapeHtml(x.sku||'')} · ${businessMoney(x.price||0)} netto</span></button>`).join('')||'<div class="business-empty compact">Keine Artikel gefunden.</div>';box._items=d.items||[];box.querySelectorAll('[data-op]').forEach(b=>b.onclick=async()=>{const x=box._items[+b.dataset.op],l=HCA103.orderLines[i];l.product_id=String(x.product_id||'');l.description=x.name||'';l.sku=x.sku||'';l.unit_price=Number(x.price)||0;l.config.shop_areas=Array.isArray(x.areas)?x.areas:[];l.config.color=x.color||'';try{await hca103ShopPrice(l)}catch{}hca103RenderOrderLines()})}catch(e){box.innerHTML=`<div class="business-empty compact error">${escapeHtml(e.message||e)}</div>`}}
async function hca103OpenOrder(){await ensureBusinessCustomers();HCA103.orderLines=[hca103NewOrderLine()];$('#businessOrderCustomer').innerHTML=businessCustomerOptions(businessDefaultCustomerId);$('#businessOrderCustomer').value=businessDefaultCustomerId||'';$('#businessOrderSubject').value='';$('#businessOrderDue').value='';$('#businessOrderReference').value='';$('#businessOrderInternalNote').value='';hca103RenderOrderLines();businessOpenView('salesorders');$('#businessSalesOrderListPage')?.classList.add('hidden');$('#businessSalesOrderDetailPage')?.classList.add('hidden');$('#businessSalesOrderEditorPage')?.classList.remove('hidden')}
async function hca103SaveOrder(){const cid=$('#businessOrderCustomer').value;if(!cid)return alert('Bitte einen Kunden auswählen.');if(HCA103.orderLines.some(x=>Array.isArray(x.config?.available_colors)&&x.config.available_colors.length&&!x.config.color))return alert('Bitte bei jeder gefundenen Ware eine Farbe auswählen.');try{for(const l of HCA103.orderLines)if(l.product_id)await hca103ShopPrice(l);const d=await businessApi('/sales/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_id:cid,contact_id:$('#businessOrderContact').value||'',billing_address_id:$('#businessOrderBillingAddress').value||'',shipping_address_id:$('#businessOrderShippingAddress').value||'',subject:$('#businessOrderSubject').value.trim()||'Auftrag',due_date:$('#businessOrderDue').value,customer_reference:$('#businessOrderReference').value.trim(),internal_note:$('#businessOrderInternalNote').value,items:HCA103.orderLines})});$('#businessSalesOrderEditorPage')?.classList.add('hidden');await loadBusinessSalesOrders();openBusinessSalesOrder(d.item.id)}catch(e){alert('Auftrag konnte nicht gespeichert werden:\n'+(e.message||e))}}
$('#businessOrderAddLine')?.addEventListener('click',()=>{HCA103.orderLines.push(hca103NewOrderLine());hca103RenderOrderLines()});$('#businessOrderReprice')?.addEventListener('click',async()=>{for(const l of HCA103.orderLines)if(l.product_id)await hca103ShopPrice(l);hca103RenderOrderLines()});$('#saveBusinessSalesOrder')?.addEventListener('click',hca103SaveOrder);
$('#newBusinessSalesOrder')?.addEventListener('click',hca103OpenOrder);
// Schnellmenü "Auftrag" auf Direktauftrag umbiegen.
$$('[data-business-new="order"]').forEach(b=>b.addEventListener('click',e=>{e.stopImmediatePropagation();hca103OpenOrder()},true));

// Rechnung: Artikelsuche + Veredelungserfassung direkt in der bestehenden Maske.
const hca103RenderInvoiceOld=renderFinanceInvoiceLines;
renderFinanceInvoiceLines=function(){hca103RenderInvoiceOld();const host=$('#financeInvoiceLines');if(!host)return;host.querySelectorAll('[data-finance-line]').forEach((row,i)=>{const l=financeInvoiceLines[i];if(!l.config)l.config={production_steps:[]};const desc=row.querySelector('[data-fline="description"]');if(desc&&!row.querySelector('[data-inv-search]')){const search=document.createElement('input');search.className='text-input';search.placeholder='Artikel suchen (z. B. ID001)';search.dataset.invSearch=i;row.insertBefore(search,desc);search.oninput=()=>{clearTimeout(HCA103.invoiceSearchTimers[i]);HCA103.invoiceSearchTimers[i]=setTimeout(()=>hca103InvoiceSearch(i,search.value,row),120)};const ref=document.createElement('button');ref.type='button';ref.className='business-mini-action';ref.textContent=(l.config.production_steps||[]).length?'V':'+';ref.title='Veredelung hinzufügen/entfernen';ref.onclick=()=>{l.config.production_steps=(l.config.production_steps||[]).length?[]:[{technique:'stick',position:'',motif:'',colors_count:1,unit_price:0,setup_price:0}];renderFinanceInvoiceLines()};row.appendChild(ref);if((l.config.production_steps||[]).length){const extra=document.createElement('div');extra.className='finance-refinement-inline';extra.innerHTML=`<select class="text-input" data-if-tech>${Object.entries(BUSINESS_TECHNIQUES).map(([k,v])=>`<option value="${k}" ${l.config.production_steps[0].technique===k?'selected':''}>${escapeHtml(v)}</option>`).join('')}</select><input class="text-input" data-if-pos placeholder="Position" value="${escapeHtml(l.config.production_steps[0].position||'')}"><input class="text-input" data-if-motif placeholder="Motiv" value="${escapeHtml(l.config.production_steps[0].motif||'')}">`;row.appendChild(extra);extra.querySelector('[data-if-tech]').onchange=e=>l.config.production_steps[0].technique=e.target.value;extra.querySelector('[data-if-pos]').oninput=e=>l.config.production_steps[0].position=e.target.value;extra.querySelector('[data-if-motif]').oninput=e=>l.config.production_steps[0].motif=e.target.value}}})}
async function hca103InvoiceSearch(i,q,row){if(String(q).trim().length<2)return;try{const d=await businessApi(`/woocommerce/products/search?q=${encodeURIComponent(q)}&limit=8`),x=(d.items||[])[0];if(!x)return;const l=financeInvoiceLines[i];l.product_id=String(x.product_id||'');l.description=x.name||'';l.sku=x.sku||'';l.unit_price=Number(x.price)||0;l.config=l.config||{production_steps:[]};l.config.shop_areas=Array.isArray(x.areas)?x.areas:[];try{const r=await hca103ShopPrice(l);l.unit_price=(Number(r.total_netto)||0)/hca103Qty(l)}catch{}renderFinanceInvoiceLines()}catch{}}
