const hcaUnifiedSearchTimers={};

function hcaProductVariantData(x={}){
  return {product_id:String(x.product_id||x.variation_id||''),variation_id:String(x.variation_id||''),name:x.name||'',sku:x.sku||'',color:x.color||'',price:Number(x.price)||0,sizes:Array.isArray(x.sizes)?x.sizes:[],size_skus:x.size_skus||{},areas:Array.isArray(x.areas)?x.areas:[],product_type:x.product_type||'',manufacturer:x.manufacturer||'',supplier:x.supplier||'',weight:x.weight||'',dimensions:x.dimensions||{},image:x.image||''};
}
function hcaMainProductName(x={}){
  let name=String(x.name||x.title||'Artikel').trim(),color=String(x.color||'').trim();if(!color)return name;
  const escaped=color.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return name.replace(new RegExp(`\\s*(?:[-–|,/]|\\()\\s*${escaped}\\s*\\)?$`,'i'),'').trim()||name;
}
function hcaMainProductKey(x={}){
  const parent=x.parent_product_id||x.parent_id||x.main_product_id||x.base_product_id||'';
  if(parent)return `id:${parent}`;
  return `name:${hcaMainProductName(x).toLocaleLowerCase('de-DE')}`;
}
function hcaGroupMainProducts(items=[]){
  const groups=new Map();
  items.forEach(raw=>{const x=hcaProductVariantData(raw),key=hcaMainProductKey(raw);if(!groups.has(key))groups.set(key,{...raw,name:hcaMainProductName(raw),_variants:[]});groups.get(key)._variants.push(x)});
  return [...groups.values()].map(main=>{const colors=[...new Set(main._variants.map(x=>String(x.color||'').trim()).filter(Boolean))];return {...main,_colors:colors,_variantCount:main._variants.length,sku:main.parent_sku||main.base_sku||main.sku||''}});
}
function hcaApplyVariantColor(line,color){
  if(!line)return;line.config=line.config||{};line.config.color=color||'';
  const variants=Array.isArray(line.config.product_variants)?line.config.product_variants:[];
  const variant=variants.find(x=>String(x.color||'')===String(color||''))||(!color&&variants.length===1?variants[0]:null);
  if(!variant){line.product_id='';line.sku=line.config.main_sku||'';line.config.available_sizes=[];line.config.size_skus={};line.config.sizes={};return}
  const previousSizes=line.config.sizes||{},availableSizes=Array.isArray(variant.sizes)?variant.sizes:[];
  line.product_id=String(variant.product_id||variant.variation_id||line.config.main_product_id||'');line.sku=variant.sku||line.config.main_sku||line.sku||'';line.unit_price=Number(variant.price)||line.unit_price||0;line.config.available_sizes=availableSizes;line.config.size_skus=variant.size_skus||{};line.config.shop_areas=Array.isArray(variant.areas)?variant.areas:[];for(const key of ['manufacturer','supplier','weight','dimensions','image'])if(variant[key]!==undefined)line.config[key]=variant[key];line.config.sizes=Object.fromEntries(availableSizes.map(size=>[size,Math.max(0,Number(previousSizes[size])||0)]));if(availableSizes.length)line.quantity=Object.values(line.config.sizes).reduce((sum,value)=>sum+(Number(value)||0),0);
}
function hcaSelectMainProduct(line,main){
  if(!line||!main)return;const variants=(main._variants||[]).map(hcaProductVariantData),colors=[...new Set(variants.map(x=>String(x.color||'').trim()).filter(Boolean))];line.config=line.config||{};line.description=main.name||line.description;line.config.main_product_id=String(main.parent_product_id||main.parent_id||main.main_product_id||main.base_product_id||main.product_id||'');line.config.main_sku=main.parent_sku||main.base_sku||main.sku||'';line.config.product_variants=variants;line.config.available_colors=colors;line.config.color='';line.sku=line.config.main_sku;line.product_id='';line.unit_price=Number(main.price)||Number(variants[0]?.price)||line.unit_price||0;line.config.shop_areas=Array.isArray(main.areas)?main.areas:[];
  if(!colors.length){const v=variants[0]||hcaProductVariantData(main);hcaApplyVariantColor(line,v.color||'');line.product_id=String(v.product_id||line.config.main_product_id||'')}
  line.config.product_type=(Array.isArray(main.sizes)&&main.sizes.length)||variants.some(x=>x.sizes.length)?'textile':(line.config.product_type||'promotional');
}
function hcaColorFieldHtml(line,i,locked){
  const cfg=line.config||{},colors=Array.isArray(cfg.available_colors)?cfg.available_colors.filter(Boolean):[];
  if(!colors.length)return `<input class="text-input" data-bq-field="color" data-bq-index="${i}" value="${escapeHtml(cfg.color||'')}" placeholder="Farbe" ${locked?'disabled':''}>`;
  return `<select class="text-input hca-product-color" data-bq-field="color" data-bq-index="${i}" ${locked?'disabled':''}><option value="">Farbe auswählen …</option>${colors.map(c=>`<option value="${escapeHtml(c)}" ${String(cfg.color||'')===String(c)?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select>`;
}
function hcaUnifiedPositionHtml(line,i,locked=false){
  line.config=line.config||{};const cfg=line.config,type=cfg.product_type||'textile',steps=Array.isArray(cfg.production_steps)?cfg.production_steps:[],sizeMode=type==='textile';
  return `<article class="business-quote-line" data-bq-line="${i}"><div class="business-quote-line-head"><div><span>Position ${i+1}</span><strong>${escapeHtml(line.description||'Neue Position')}</strong></div>${locked?'':`<div class="actions-row"><button class="btn secondary compact" data-bq-duplicate="${i}" type="button">Duplizieren</button><button class="btn danger compact" data-bq-remove="${i}" type="button">Entfernen</button></div>`}</div><div class="business-product-search"><label>Hauptartikel suchen</label><input class="text-input" data-bq-search="${i}" placeholder="Hauptartikel nach Name oder Artikelnummer suchen …" ${locked?'disabled':''}><div class="business-product-search-results hidden" data-bq-results="${i}"></div></div><div class="business-form-grid quote-line-grid"><div><label>Art</label><select class="text-input" data-bq-field="product_type" data-bq-index="${i}" ${locked?'disabled':''}><option value="textile" ${type==='textile'?'selected':''}>Textil</option><option value="promotional" ${type==='promotional'?'selected':''}>Werbeartikel</option><option value="service" ${type==='service'?'selected':''}>Dienstleistung</option></select></div><div class="span-2"><label>Bezeichnung</label><input class="text-input" data-bq-field="description" data-bq-index="${i}" value="${escapeHtml(line.description||'')}" ${locked?'disabled':''}></div><div><label>SKU / Art.-Nr.</label><input class="text-input" data-bq-field="sku" data-bq-index="${i}" value="${escapeHtml(line.sku||'')}" ${locked?'disabled':''}></div><div><label>Farbe</label>${hcaColorFieldHtml(line,i,locked)}</div><div><label>Einzelpreis netto</label><input class="text-input" data-bq-field="unit_price" data-bq-index="${i}" type="number" step="0.01" min="0" value="${Number(line.unit_price)||0}" ${locked?'disabled':''}></div><div><label>Rabatt %</label><input class="text-input" data-bq-field="discount_pct" data-bq-index="${i}" type="number" step="0.1" min="0" max="100" value="${Number(line.discount_pct)||0}" ${locked?'disabled':''}></div><div><label>MwSt. %</label><input class="text-input" data-bq-field="tax_rate" data-bq-index="${i}" type="number" step="0.1" min="0" value="${Number(line.tax_rate)||0}" ${locked?'disabled':''}></div></div>${sizeMode?`<div class="business-line-section"><div class="business-line-section-title"><b>Größen &amp; Mengen</b><span>Gesamtmenge wird automatisch berechnet.</span></div>${businessSizeInputs(line,i,locked)}</div>`:`<div class="business-line-section business-qty-row"><label>Menge</label><input class="text-input" data-bq-field="quantity" data-bq-index="${i}" type="number" min="1" step="1" value="${Number(line.quantity)||1}" ${locked?'disabled':''}></div>`}<div class="business-line-section"><div class="business-line-section-title"><b>Veredelung</b><span>Preis pro Stück · Einrichtung einmalig · Druckfarben</span>${locked?'':`<button class="btn secondary compact" data-bq-step-add="${i}" type="button">+ Veredelung</button>`}</div><div class="business-step-list">${steps.length?steps.map((x,si)=>businessStepRow(x,i,si,locked)).join(''):'<div class="business-empty compact">Noch keine Veredelung. Bei unveredelter Ware kann dies leer bleiben.</div>'}</div></div><div class="business-quote-line-sum"><span>Positionssumme brutto</span><strong>${businessMoney(businessQuoteLineTotal(line))}</strong></div></article>`;
}
businessQuoteLineHtml=hcaUnifiedPositionHtml;

async function hcaSearchMainProducts(i,query,box,lines,rerender){
  query=String(query||'').trim();if(!box)return;if(query.length<2){box.classList.add('hidden');box.innerHTML='';return}box.classList.remove('hidden');box.innerHTML='<div class="business-loading compact">Hauptartikel werden gesucht …</div>';
  try{const res=await productionFetch(`/api/hca-shared/woocommerce/products/search?q=${encodeURIComponent(query)}&limit=100`,{timeoutMs:30000}),d=await res.json();if(!res.ok)throw new Error(d.detail||d.error||`HTTP ${res.status}`);const mains=hcaGroupMainProducts(d.items||[]);box.innerHTML=mains.length?mains.map((x,n)=>`<button type="button" data-hca-main-product="${n}"><b>${escapeHtml(x.name||'Artikel')}</b><span>${escapeHtml([x.sku?`Art.-Nr. ${x.sku}`:'',x._colors.length?`${x._colors.length} Farbe${x._colors.length===1?'':'n'}`:'ohne Farbvarianten',x._variantCount>1?`${x._variantCount} Varianten`:''].filter(Boolean).join(' · '))}</span></button>`).join(''):'<div class="business-empty compact">Keine Hauptartikel gefunden.</div>';box._mainItems=mains;box.querySelectorAll('[data-hca-main-product]').forEach(b=>b.onclick=async()=>{const line=lines[Number(i)],main=box._mainItems?.[Number(b.dataset.hcaMainProduct)];if(!line||!main)return;hcaSelectMainProduct(line,main);if(line.product_id)try{await hca103ShopPrice(line)}catch{}rerender()})}catch(err){box.innerHTML=`<div class="business-empty compact error">${escapeHtml(err.message||String(err))}</div>`}
}
searchBusinessQuoteProducts=(i,query)=>hcaSearchMainProducts(i,query,$(`[data-bq-results="${i}"]`),activeBusinessQuote?.items||[],renderBusinessQuoteEditor);

function hcaPositionSum(host,line,i){const sum=host.querySelector(`[data-bq-line="${i}"] .business-quote-line-sum strong`);if(sum)sum.textContent=businessMoney(businessQuoteLineTotal(line))}
function hcaBindPositionForm(host,lines,rerender,onTotals=()=>{}){
  if(!host)return;
  host.querySelectorAll('[data-bq-field]').forEach(el=>el.addEventListener('input',()=>{const i=Number(el.dataset.bqIndex),f=el.dataset.bqField,line=lines[i];if(!line)return;if(f==='product_type'){line.config.product_type=el.value;rerender();return}if(f==='color'){line.config.color=el.value}else if(['unit_price','discount_pct','tax_rate','quantity'].includes(f))line[f]=Number(el.value)||0;else line[f]=el.value;onTotals();hcaPositionSum(host,line,i)}));
  host.querySelectorAll('.hca-product-color').forEach(el=>el.addEventListener('change',async()=>{const i=Number(el.dataset.bqIndex),line=lines[i];hcaApplyVariantColor(line,el.value);if(line?.product_id)try{await hca103ShopPrice(line)}catch{}rerender()}));
  host.querySelectorAll('[data-bq-size]').forEach(el=>el.addEventListener('input',()=>{const i=Number(el.dataset.bqIndex),line=lines[i];line.config.sizes=line.config.sizes||{};line.config.sizes[el.dataset.bqSize]=Math.max(0,Number(el.value)||0);line.quantity=Object.values(line.config.sizes).reduce((a,v)=>a+(Number(v)||0),0);onTotals();hcaPositionSum(host,line,i)}));
  host.querySelectorAll('[data-bq-remove]').forEach(b=>b.onclick=()=>{lines.splice(Number(b.dataset.bqRemove),1);if(!lines.length)lines.push(newBusinessQuoteLine());rerender()});
  host.querySelectorAll('[data-bq-duplicate]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.bqDuplicate),x=JSON.parse(JSON.stringify(lines[i]));x.id=crypto.randomUUID?.()||String(Date.now());lines.splice(i+1,0,newBusinessQuoteLine(x));rerender()});
  host.querySelectorAll('[data-bq-step-add]').forEach(b=>b.onclick=()=>{const line=lines[Number(b.dataset.bqStepAdd)];line.config.production_steps=line.config.production_steps||[];line.config.production_steps.push({technique:'stick',position:'',motif:'',unit_price:0,setup_price:0,colors_count:0});rerender()});
  host.querySelectorAll('[data-bq-step-remove]').forEach(b=>b.onclick=()=>{const [i,si]=b.dataset.bqStepRemove.split(':').map(Number);lines[i].config.production_steps.splice(si,1);rerender()});
  host.querySelectorAll('[data-bq-step-tech],[data-bq-step-pos],[data-bq-step-motif],[data-bq-step-unit],[data-bq-step-setup],[data-bq-step-colors]').forEach(el=>el.addEventListener('input',()=>{const found=['bqStepTech','bqStepPos','bqStepMotif','bqStepUnit','bqStepSetup','bqStepColors'].find(k=>el.dataset[k]!==undefined);if(!found)return;const [i,si]=el.dataset[found].split(':').map(Number),step=lines[i]?.config?.production_steps?.[si];if(!step)return;const field={bqStepTech:'technique',bqStepPos:'position',bqStepMotif:'motif',bqStepUnit:'unit_price',bqStepSetup:'setup_price',bqStepColors:'colors_count'}[found];step[field]=['unit_price','setup_price','colors_count'].includes(field)?Math.max(0,Number(el.value)||0):el.value;onTotals();hcaPositionSum(host,lines[i],i)}));
  host.querySelectorAll('[data-bq-search]').forEach(el=>el.addEventListener('input',()=>{const i=Number(el.dataset.bqSearch),key=`${host.id}:${i}`;clearTimeout(hcaUnifiedSearchTimers[key]);hcaUnifiedSearchTimers[key]=setTimeout(()=>hcaSearchMainProducts(i,el.value,host.querySelector(`[data-bq-results="${i}"]`),lines,rerender),120)}));
}

const hcaQuoteBinderBeforeUnified=bindBusinessQuoteEditor;
bindBusinessQuoteEditor=function(){hcaQuoteBinderBeforeUnified();const host=$('#businessQuoteEditor');host?.querySelectorAll('.hca-product-color').forEach(el=>el.addEventListener('change',async()=>{const line=activeBusinessQuote?.items?.[Number(el.dataset.bqIndex)];hcaApplyVariantColor(line,el.value);if(line?.product_id)try{await hca103ShopPrice(line)}catch{}renderBusinessQuoteEditor()}))};

hca103RenderOrderLines=function(){const host=$('#businessOrderLines');if(!host)return;host.innerHTML=HCA103.orderLines.map((line,i)=>hcaUnifiedPositionHtml(line,i,false)).join('');hcaBindPositionForm(host,HCA103.orderLines,hca103RenderOrderLines)};
