function hcaV121Area(line,step){const areas=hcaV121Areas(line);return areas.find(a=>String(a.id||'')===String(step.area_id||''))||areas.find(a=>Number(a.index)===Number(step.area_index))||areas[0]||null}
function hcaV121Assignment(area,step){const list=Array.isArray(area?.assignments)?area.assignments:[];return list.find(a=>Number(a.druckart_id)===Number(step.druckart_id))||list[0]||null}
function hcaV121ApplyAssignment(step,area,assignment){
  if(!step||!area||!assignment)return;step.manual_override=false;step.area_id=area.id||'';step.area_index=Number(area.index)||0;step.area_name=area.name||'';step.position=area.name||area.position||'';step.druckart_id=Number(assignment.druckart_id)||0;step.technique=assignment.method?.code||String(step.druckart_id);step.technique_label=assignment.method?.name||((assignment.method?.label&&assignment.method.label!=='Array')?assignment.method.label:'Veredelung');step.cost_id=Number(assignment.cost_id)||0;step.bearbeitung_cost_id=Number(assignment.bearbeitung_cost_id)||0;step.max_colors=Math.max(1,Number(assignment.max_colors)||1);step.colors_count=Math.max(1,Math.min(step.max_colors,Number(step.colors_count)||1));const setup=String(assignment.setup?.label||'').trim();step.setup_label=/^Einrichtungskosten/i.test(setup)?setup:`Einrichtungskosten${setup?' '+setup:''}`;step.handling_label='Bearbeitungskosten/Artikel';
}
