function hcaV121BindWizardControls(host,lines,rerender){
  if(!host)return;
  host.querySelectorAll('[data-hca-step-area]').forEach(el=>el.addEventListener('change',()=>{const [i,si]=el.dataset.hcaStepArea.split(':').map(Number),line=lines[i],step=line?.config?.production_steps?.[si],area=hcaV121Areas(line).find(a=>Number(a.index)===Number(el.value));hcaV121ApplyAssignment(step,area,(area?.assignments||[])[0]);hcaV121SchedulePrice(line,rerender,`${host.id}:${i}`);rerender()}));
  host.querySelectorAll('[data-hca-step-method]').forEach(el=>el.addEventListener('change',()=>{const [i,si]=el.dataset.hcaStepMethod.split(':').map(Number),line=lines[i],step=line?.config?.production_steps?.[si],area=hcaV121Area(line,step),a=(area?.assignments||[]).find(x=>Number(x.druckart_id)===Number(el.value));hcaV121ApplyAssignment(step,area,a);hcaV121SchedulePrice(line,rerender,`${host.id}:${i}`);rerender()}));
  host.querySelectorAll('[data-hca-step-manual]').forEach(el=>el.addEventListener('change',()=>{const [i,si]=el.dataset.hcaStepManual.split(':').map(Number),line=lines[i],step=line?.config?.production_steps?.[si];if(!step)return;step.manual_override=el.checked;if(!el.checked){const area=hcaV121Area(line,step);hcaV121ApplyAssignment(step,area,hcaV121Assignment(area,step));hcaV121SchedulePrice(line,rerender,`${host.id}:${i}`)}rerender()}));
  for(const attr of ['hcaStepPrint','hcaStepHandling'])host.querySelectorAll(`[data-${attr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}]`).forEach(el=>el.addEventListener('input',()=>{const [i,si]=el.dataset[attr].split(':').map(Number),line=lines[i],step=line?.config?.production_steps?.[si];if(!step)return;if(attr==='hcaStepPrint')step.print_price=Math.max(0,Number(el.value)||0);else step.handling_price=Math.max(0,Number(el.value)||0);step.unit_price=(Number(step.print_price)||0)+(Number(step.handling_price)||0)}));
  host.querySelectorAll('[data-bq-step-tech]').forEach(el=>el.addEventListener('input',()=>{const [i,si]=el.dataset.bqStepTech.split(':').map(Number),step=lines[i]?.config?.production_steps?.[si];if(step?.manual_override)step.technique_label=el.value}));
  host.querySelectorAll('[data-bq-field="quantity"],[data-bq-size],[data-bq-step-colors]').forEach(el=>el.addEventListener('change',()=>{const raw=el.dataset.bqIndex??String(el.dataset.bqStepColors||'').split(':')[0],i=Number(raw),line=lines[i];hcaV121SchedulePrice(line,rerender,`${host.id}:${i}`)}));
}
