updateBusinessQuoteTotals=function(){if(!activeBusinessQuote)return;let net=0,tax=0,gross=0;for(const line of activeBusinessQuote.items||[]){if(['optional','text'].includes(String(line.item_type||'product').toLowerCase()))continue;const a=businessQuoteLineAmounts(line);net+=a.net;tax+=a.tax;gross+=a.gross}const el=$('#businessQuoteTotals');if(el)el.innerHTML=`<div><span>Netto</span><strong>${businessMoney(net)}</strong></div><div><span>MwSt.</span><strong>${businessMoney(tax)}</strong></div><div class="grand"><span>Brutto</span><strong>${businessMoney(gross)}</strong></div>`};

