let hcaV123PreviewUrl='';
async function hcaV123DocumentPreview(){
  if(!activeBusinessQuote)return;const payload=businessQuotePayload();payload.source_channel=activeBusinessQuote.source_channel||'';payload.payment_term_id=activeBusinessQuote.payment_term_id||'';
  try{
    const response=await productionFetch('/api/hca-shared/sales/quotes/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store',timeoutMs:60000});
    if(!response.ok){let message=`HTTP ${response.status}`;try{const data=await response.json();message=data.detail||data.error||message}catch{}throw new Error(message)}
    if(hcaV123PreviewUrl)URL.revokeObjectURL(hcaV123PreviewUrl);hcaV123PreviewUrl=URL.createObjectURL(await response.blob());
    const frame=$('#businessDocumentPreviewFrame'),dialog=$('#businessDocumentPreviewDialog');if(frame)frame.src=hcaV123PreviewUrl;if(dialog&&!dialog.open)dialog.showModal();
  }catch(err){alert(`Dokumentenvorschau konnte nicht erstellt werden:\n${err.message||err}`)}
}
$('#businessDocumentPreviewDialog')?.addEventListener('close',()=>{const frame=$('#businessDocumentPreviewFrame');if(frame)frame.src='about:blank';if(hcaV123PreviewUrl){URL.revokeObjectURL(hcaV123PreviewUrl);hcaV123PreviewUrl=''}});

function hcaV123MoveQuoteLine(index,direction){
  const items=activeBusinessQuote?.items||[],target=index+direction;if(target<0||target>=items.length)return;syncBusinessQuoteHeader();[items[index],items[target]]=[items[target],items[index]];hcaEditorDirty=true;renderBusinessQuoteEditor();setTimeout(()=>$(`[data-bq-line="${target}"]`)?.scrollIntoView({block:'center'}),0)
}
function hcaV123AddQuoteLine(type='product'){
  if(!activeBusinessQuote)return;syncBusinessQuoteHeader();activeBusinessQuote.items.push(newBusinessQuoteLine({item_type:type,description:type==='text'?'':''}));hcaEditorDirty=true;renderBusinessQuoteEditor();setTimeout(()=>$(`[data-bq-line="${activeBusinessQuote.items.length-1}"]`)?.scrollIntoView({block:'center'}),0)
}
function hcaV123PositionControls(){
  const q=activeBusinessQuote,host=$('#businessQuoteLines');if(!q||!host)return;const locked=['accepted','rejected','expired'].includes(q.status);
  host.querySelectorAll('[data-bq-line]').forEach((card,i)=>{if(locked)return;const actions=card.querySelector('.business-quote-line-head .actions-row');if(!actions)return;actions.insertAdjacentHTML('afterbegin',`<button class="btn secondary compact hca-move-position" data-hca-move-up="${i}" type="button" title="Position nach oben" ${i===0?'disabled':''}>↑</button><button class="btn secondary compact hca-move-position" data-hca-move-down="${i}" type="button" title="Position nach unten" ${i===q.items.length-1?'disabled':''}>↓</button>`)});
  host.querySelectorAll('[data-hca-move-up]').forEach(b=>b.onclick=()=>hcaV123MoveQuoteLine(Number(b.dataset.hcaMoveUp),-1));host.querySelectorAll('[data-hca-move-down]').forEach(b=>b.onclick=()=>hcaV123MoveQuoteLine(Number(b.dataset.hcaMoveDown),1));
  if(!locked)host.insertAdjacentHTML('afterend','<div class="hca-position-add-bottom"><span>Weitere Position hinzufügen</span><div class="actions-row"><button class="btn primary" id="businessAddQuoteLineBottom" type="button">+ Artikelposition</button><button class="btn secondary" id="businessAddOptionalLineBottom" type="button">+ Optionale Position</button><button class="btn secondary" id="businessAddTextLineBottom" type="button">+ Textposition</button></div></div>');
  $('#businessAddQuoteLineBottom')?.addEventListener('click',()=>hcaV123AddQuoteLine('product'));$('#businessAddOptionalLineBottom')?.addEventListener('click',()=>hcaV123AddQuoteLine('optional'));$('#businessAddTextLineBottom')?.addEventListener('click',()=>hcaV123AddQuoteLine('text'));
}
function hcaV123ArrangeQuoteActions(){
  const actions=$('#businessQuoteTopActions');if(!actions||!activeBusinessQuote)return;
  const preview=document.createElement('button');preview.className='btn secondary';preview.id='businessQuoteDocumentPreview';preview.type='button';preview.textContent='◉ Dokumentenvorschau';preview.onclick=hcaV123DocumentPreview;actions.prepend(preview);
  const direct=$('#businessDirectPrintQuote');if(direct){direct.classList.remove('icon-only');direct.textContent='🖨 Direktdruck';direct.title='Ohne Druckdialog an den festgelegten Dokumentendrucker senden'}
  const print=$('#businessPrintQuote');if(print)print.textContent='▣ Druckvorschau';
  const mail=$('#businessQuoteEmail');if(mail)mail.textContent='✉ Angebot senden';
  const documentGroup=document.createElement('div');documentGroup.className='hca-quote-action-group document-actions';
  [direct,print,preview,mail].filter(Boolean).forEach(button=>documentGroup.appendChild(button));
  const workflowGroup=document.createElement('div');workflowGroup.className='hca-quote-action-group workflow-actions';
  [...actions.children].forEach(button=>workflowGroup.appendChild(button));
  actions.append(documentGroup,workflowGroup);
}
const hcaV123QuoteRender=renderBusinessQuoteEditor;
renderBusinessQuoteEditor=function(){hcaV123QuoteRender();hcaV123PositionControls();hcaV123ArrangeQuoteActions()};

// HCA v0.13.0 · Lieferanten, eigene Artikel und Woo-Kundenportal
let hcaSupplierCache=[],hcaEditingSupplierId='';
async function loadHcaSuppliers(){const host=$('#hcaSupplierList');if(!host||!productionServerConfigured())return;host.innerHTML='<div class="business-loading">Lieferanten werden geladen …</div>';const q=String($('#hcaSupplierSearch')?.value||'').trim();try{const d=await businessApi(`/crm/suppliers?q=${encodeURIComponent(q)}&active=1&limit=1000`);hcaSupplierCache=d.items||[];renderHcaSuppliers()}catch(err){host.innerHTML=`<div class="business-empty error">Lieferanten konnten nicht geladen werden: ${escapeHtml(err.message||String(err))}</div>`}}
function renderHcaSuppliers(){const host=$('#hcaSupplierList');if(!host)return;if(!hcaSupplierCache.length){host.innerHTML='<div class="business-empty"><b>Noch keine Lieferanten angelegt.</b><span>Hersteller und Lieferant werden im Artikelstamm getrennt geführt.</span></div>';return}host.innerHTML=`<div class="business-list-head hca-supplier-grid"><span>Lieferant</span><span>Kontakt</span><span>Ort</span><span>Kundennummer</span><span></span></div>${hcaSupplierCache.map(s=>`<button class="business-list-row hca-supplier-grid" data-hca-supplier="${escapeHtml(s.id)}"><span class="business-main-cell"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.code||'')}</small></span><span>${escapeHtml(s.contact_name||s.email||s.phone||'–')}</span><span>${escapeHtml([s.zip,s.city].filter(Boolean).join(' ')||'–')}</span><span>${escapeHtml(s.customer_no||'–')}</span><span class="business-row-arrow">›</span></button>`).join('')}`;host.querySelectorAll('[data-hca-supplier]').forEach(b=>b.onclick=()=>openHcaSupplier(hcaSupplierCache.find(x=>String(x.id)===String(b.dataset.hcaSupplier))||{}))}
function openHcaSupplier(s={}){hcaEditingSupplierId=s.id||'';$('#hcaSupplierDialogTitle').textContent=s.id?'Lieferant bearbeiten':'Lieferant anlegen';const values={hcaSupplierName:s.name,hcaSupplierCode:s.code,hcaSupplierCustomerNo:s.customer_no,hcaSupplierContact:s.contact_name,hcaSupplierEmail:s.email,hcaSupplierPhone:s.phone,hcaSupplierWebsite:s.website,hcaSupplierStreet:s.street,hcaSupplierZip:s.zip,hcaSupplierCity:s.city,hcaSupplierCountry:s.country||'DE',hcaSupplierNotes:s.notes};Object.entries(values).forEach(([id,value])=>{const el=$('#'+id);if(el)el.value=value||''});$('#hcaSupplierDialog')?.showModal()}
async function saveHcaSupplier(){const payload={name:$('#hcaSupplierName').value.trim(),code:$('#hcaSupplierCode').value.trim(),customer_no:$('#hcaSupplierCustomerNo').value.trim(),contact_name:$('#hcaSupplierContact').value.trim(),email:$('#hcaSupplierEmail').value.trim(),phone:$('#hcaSupplierPhone').value.trim(),website:$('#hcaSupplierWebsite').value.trim(),street:$('#hcaSupplierStreet').value.trim(),zip:$('#hcaSupplierZip').value.trim(),city:$('#hcaSupplierCity').value.trim(),country:$('#hcaSupplierCountry').value.trim()||'DE',notes:$('#hcaSupplierNotes').value.trim(),active:true};try{await businessApi(hcaEditingSupplierId?`/crm/suppliers/${encodeURIComponent(hcaEditingSupplierId)}`:'/crm/suppliers',{method:hcaEditingSupplierId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#hcaSupplierDialog').close();await loadHcaSuppliers()}catch(err){alert(`Lieferant konnte nicht gespeichert werden:\n${err.message||err}`)}}

async function openHcaOwnArticle(){if(!hcaSupplierCache.length)try{const d=await businessApi('/crm/suppliers?active=1&limit=1000');hcaSupplierCache=d.items||[]}catch{}$('#hcaOwnArticleSupplier').innerHTML='<option value="">Kein Lieferant gewählt</option>'+hcaSupplierCache.map(s=>`<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`).join('');['hcaOwnArticleName','hcaOwnArticleSku','hcaOwnArticleManufacturer','hcaOwnArticleDescription'].forEach(id=>{$('#'+id).value=''});$('#hcaOwnArticlePrice').value='0';$('#hcaOwnArticleTax').value='19';$('#hcaOwnArticleShop').checked=false;$('#hcaOwnArticleShopStatus').value='draft';$('#hcaOwnArticleShopStatusWrap').classList.add('hidden');$('#hcaOwnArticleDialog')?.showModal()}
async function saveHcaOwnArticle(){const select=$('#hcaOwnArticleSupplier'),supplierId=select.value,supplier=select.options[select.selectedIndex]?.textContent||'';const payload={name:$('#hcaOwnArticleName').value.trim(),sku:$('#hcaOwnArticleSku').value.trim(),manufacturer:$('#hcaOwnArticleManufacturer').value.trim(),supplier_id:supplierId,supplier:supplierId?supplier:'',description:$('#hcaOwnArticleDescription').value.trim(),unit_price:Number($('#hcaOwnArticlePrice').value)||0,tax_rate:Number($('#hcaOwnArticleTax').value)||19,list_in_shop:$('#hcaOwnArticleShop').checked,shop_status:$('#hcaOwnArticleShopStatus').value};try{const d=await businessApi('/inventory/articles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#hcaOwnArticleDialog').close();await loadInventory();if(d.article?.id)await openInventoryArticle(d.article.id,true);alert(d.woo_created?'Artikel wurde in HCA und WooCommerce angelegt.':'Artikel wurde nur im HCA-Artikelstamm angelegt.')}catch(err){alert(`Artikel konnte nicht angelegt werden:\n${err.message||err}`)}}

async function hcaV130SyncCustomersAndPortal(showResult=true){if(!productionServerConfigured())return;const button=$('#syncWooCustomersPortal');if(button){button.disabled=true;button.textContent='Abgleich läuft …'}try{const customers=await businessApi('/woocommerce/customers/sync',{method:'POST',timeoutMs:120000});businessCustomerCache=[];await loadBusinessCustomers();const portal=await businessApi('/woocommerce/customer-portal/sync',{method:'POST',timeoutMs:300000});if(showResult)alert(`Abgleich abgeschlossen.\n\nShopkunden: ${customers.remote||0}\nNeu in HCA: ${customers.created||0}\nZusammengeführt: ${customers.merged||0}\nKundenportal-Dokumente: ${portal.documents||0}`);return {customers,portal}}catch(err){if(showResult)alert(`Shopkunden- und Portalabgleich fehlgeschlagen:\n${err.message||err}`);throw err}finally{if(button){button.disabled=false;button.textContent='Shopkunden & Portal abgleichen'}}}
async function hcaV130AutomaticWooSync(){if(!productionServerConfigured())return;const now=Date.now(),last=Number(localStorage.getItem('hcaWooCustomerSyncAt')||0),portalLast=Number(localStorage.getItem('hcaWooPortalSyncAt')||0);if(now-last<15*60*1000)return;try{await businessApi('/woocommerce/customers/sync',{method:'POST',timeoutMs:120000});localStorage.setItem('hcaWooCustomerSyncAt',String(now));businessCustomerCache=[];if(now-portalLast>60*60*1000){await businessApi('/woocommerce/customer-portal/sync',{method:'POST',timeoutMs:300000});localStorage.setItem('hcaWooPortalSyncAt',String(now))}}catch(err){console.warn('Automatischer WooCommerce-Kundenabgleich',err)}}

const hcaV130ShowView=showView;showView=function(name,categoryOverride='',inventoryTarget=''){hcaV130ShowView(name,categoryOverride,inventoryTarget);if(name==='suppliers')loadHcaSuppliers()};
$('#openHcaSupplier')?.addEventListener('click',()=>openHcaSupplier({}));$('#reloadHcaSuppliers')?.addEventListener('click',loadHcaSuppliers);$('#saveHcaSupplier')?.addEventListener('click',saveHcaSupplier);$('#hcaSupplierSearch')?.addEventListener('input',()=>{clearTimeout(businessGlobalSearchTimer);businessGlobalSearchTimer=setTimeout(loadHcaSuppliers,250)});$('#openHcaOwnArticle')?.addEventListener('click',openHcaOwnArticle);$('#saveHcaOwnArticle')?.addEventListener('click',saveHcaOwnArticle);$('#hcaOwnArticleShop')?.addEventListener('change',e=>$('#hcaOwnArticleShopStatusWrap')?.classList.toggle('hidden',!e.target.checked));$('#syncWooCustomersPortal')?.addEventListener('click',()=>hcaV130SyncCustomersAndPortal(true));setTimeout(hcaV130AutomaticWooSync,7000);setInterval(hcaV130AutomaticWooSync,15*60*1000);
